static uint8_t uhf_signal_bar_level(uint32_t raw_rssi, size_t epc_bytes) {
    /* UCM601 packs mode bits above a 25-bit signal magnitude. Normalize by EPC length. */
    const uint32_t magnitude = raw_rssi & 0x01FFFFFFU;
    const uint32_t level = epc_bytes ? magnitude / epc_bytes : 0U;
    uint8_t filled = 0U;
    if(level) filled = 1U;
    if(level >= 50000U) filled = 2U;
    if(level >= 100000U) filled = 3U;
    if(level >= 150000U) filled = 4U;
    return filled;
}

static void uhf_draw_signal_bars(Canvas* canvas, uint8_t filled, int y) {
    static const uint8_t heights[4] = {4U, 5U, 7U, 8U};
    for(uint8_t i = 0U; i < 4U; i++) {
        const int x = 112 + (int)i * 4;
        const int height = heights[i];
        if(i < filled)
            canvas_draw_box(canvas, x, y - height, 3, height);
        else
            canvas_draw_frame(canvas, x, y - height, 3, height);
    }
}

static void uhf_format_list_epc_compact(
    Canvas* canvas,
    const char* epc,
    int max_width,
    char* out,
    size_t out_size) {
    if(!canvas || !out || out_size == 0U) return;

    out[0] = '\0';
    if(!epc) return;
    if(max_width <= 0) return;

    const size_t epc_len = strlen(epc);
    if(epc_len < out_size) {
        strncpy(out, epc, out_size - 1U);
        out[out_size - 1U] = '\0';
        if(canvas_string_width(canvas, out) <= max_width) return;
    }

    if(epc_len <= 8U) {
        strncpy(out, epc, out_size - 1U);
        out[out_size - 1U] = '\0';
        return;
    }

    const char* dots = "...";
    size_t prefix_len = 4U;
    size_t suffix_len = 4U;

    snprintf(
        out,
        out_size,
        "%.*s%s%.*s",
        (int)prefix_len,
        epc,
        dots,
        (int)suffix_len,
        epc + (epc_len - suffix_len));

    while(prefix_len + suffix_len < epc_len) {
        size_t next_prefix = prefix_len;
        size_t next_suffix = suffix_len;

        if(next_prefix <= next_suffix) {
            next_prefix++;
        } else {
            next_suffix++;
        }

        char candidate[40];
        snprintf(
            candidate,
            sizeof(candidate),
            "%.*s%s%.*s",
            (int)next_prefix,
            epc,
            dots,
            (int)next_suffix,
            epc + (epc_len - next_suffix));

        if(canvas_string_width(canvas, candidate) > max_width) {
            break;
        }

        prefix_len = next_prefix;
        suffix_len = next_suffix;
        strncpy(out, candidate, out_size - 1U);
        out[out_size - 1U] = '\0';
    }
}

static void uhf_draw_list_epc_distributed(Canvas* canvas, const char* epc, int y) {
    if(!canvas || !epc) return;

    char compact[40];
    uhf_format_list_epc_compact(canvas, epc, 106, compact, sizeof(compact));
    char* dots = strstr(compact, "...");
    if(!dots) {
        canvas_draw_str(canvas, 1, y, compact);
        return;
    }

    *dots = '\0';
    const char* suffix = dots + 3;
    const int prefix_width = canvas_string_width(canvas, compact);
    const int suffix_width = canvas_string_width(canvas, suffix);
    const int dots_width = canvas_string_width(canvas, "...");
    const int prefix_x = 1;
    const int prefix_end = prefix_x + prefix_width;
    const int suffix_x = 107 - suffix_width;
    int dots_x = prefix_end + (suffix_x - prefix_end - dots_width) / 2;
    if(dots_x < prefix_end) dots_x = prefix_end;

    canvas_draw_str(canvas, prefix_x, y, compact);
    canvas_draw_str(canvas, dots_x, y, "...");
    canvas_draw_str(canvas, suffix_x, y, suffix);
}

