static void uhf_prepare_csv_filename(UhfApp* app) {
    if(!app) return;
    DateTime now;
    furi_hal_rtc_get_datetime(&now);

    Storage* storage = furi_record_open(RECORD_STORAGE);
    for(unsigned index = 1U; index <= 999U; index++) {
        snprintf(
            app->csv_filename,
            sizeof(app->csv_filename),
            "uhf_%04u%02u%02u_%03u",
            (unsigned)now.year,
            (unsigned)now.month,
            (unsigned)now.day,
            index);
        char path[128];
        snprintf(path, sizeof(path), UHF_APP_DATA_DIR "/%s.csv", app->csv_filename);
        if(!storage || !storage_file_exists(storage, path)) break;
    }
    if(storage) furi_record_close(RECORD_STORAGE);
}

static void uhf_show_list_menu(UhfApp* app) {
    if(!app) return;
    if(uhf_count_tags(app) == 0U) {
        uhf_set_status(app, "No tags to save");
        return;
    }
    const bool resume = app->inventory_running;
    if(resume) {
        uhf_stop_inventory(app);
        furi_delay_ms(UHF_STOP_SETTLE_MS);
        uhf_process_rx(app);
    }
    uhf_prepare_csv_filename(app);
    if(uhf_prompt_csv_filename(app, app->csv_filename, sizeof(app->csv_filename))) {
        if(uhf_save_index_epc_csv(app, app->csv_filename)) {
            if(!app->inventory_actions_active) {
                app->page = UhfPageList;
                app->list_selection_manual = false;
            }
            uhf_set_status(app, "Saved");
            app->save_popup_csv = true;
            app->save_popup_active = true;
            view_port_update(app->view_port);
            furi_delay_ms(1200U);
            app->save_popup_active = false;
            app->save_popup_csv = false;
            view_port_update(app->view_port);
        }
    } else {
        uhf_set_status(app, "Save canceled");
    }
    if(resume) uhf_start_inventory(app);
}

static void
    uhf_set_startup_text(UhfApp* app, const char* text, const char* subtext, uint8_t dots) {
    if(!app) return;

    strncpy(app->startup_text, text ? text : "", sizeof(app->startup_text) - 1);
    app->startup_text[sizeof(app->startup_text) - 1] = '\0';

    strncpy(app->startup_subtext, subtext ? subtext : "", sizeof(app->startup_subtext) - 1);
    app->startup_subtext[sizeof(app->startup_subtext) - 1] = '\0';

    app->startup_dots = dots;
    if(app->view_port) {
        view_port_update(app->view_port);
    }
}

static void uhf_run_startup_sequence(UhfApp* app) {
    if(!app) return;

    app->startup_active = true;
    uhf_set_startup_text(app, "Initializing", "Preparing reader", 0);

    bool got_version = false;
    app->baud_rate = UHF_BAUD_RATE;
    if(!uhf_open_bridge_uart(app)) {
        uhf_diag_log(app, "Startup UART open failed");
        goto startup_done;
    }
    app->hardware_ready = true;
    uhf_diag_log(
        app,
        "Startup UART id=%u TX:%d RX:%d baud=%lu",
        (unsigned)app->serial_id,
        app->tx_ext_pin,
        app->rx_ext_pin,
        (unsigned long)app->baud_rate);

    uhf_set_startup_text(app, "Initializing", "Hardware reset", 0);
    uhf_hardware_reset_reader(app);

    if(app->rx_stream) furi_stream_buffer_reset(app->rx_stream);
    app->frame_buffer_len = 0;

    uhf_set_startup_text(app, "Initializing", "Checking reader", 0);
    got_version = uhf_try_reader_handshake(app, 1U);

    if(!got_version) {
        uhf_set_startup_text(app, "Initializing", "Power-cycle reset", 0);
        if(uhf_power_cycle_reader(app)) {
            got_version = uhf_try_reader_handshake(app, 3U);
        }
    }

startup_done:

    if(got_version) {
        char line[40];
        snprintf(
            line, sizeof(line), "Version %s @ %lu", app->version, (unsigned long)app->baud_rate);
        uhf_set_startup_text(app, "Ready", line, 0);
        uhf_set_status(app, "Ready");
        furi_delay_ms(650U);
    } else {
        char failure[40];
        snprintf(
            failure,
            sizeof(failure),
            "RX:%lu frames:%lu errors:%lu",
            (unsigned long)app->rx_bytes,
            (unsigned long)app->rx_frames,
            (unsigned long)app->rx_errors);
        uhf_diag_log(app, "Startup failed %s", failure);
        (void)uhf_save_diag_log(app);
        uhf_set_startup_text(app, "Not Ready", failure, 0);
        uhf_set_status(app, "Not Ready");
        furi_delay_ms(800U);
    }

    app->startup_active = false;
    if(app->view_port) {
        view_port_update(app->view_port);
    }
}

static bool uhf_has_version(UhfApp* app) {
    bool has = false;
    if(uhf_data_lock(app, 10)) {
        has = app->version[0] != '\0';
        uhf_data_unlock(app);
    }
    return has;
}

static void uhf_clear_version(UhfApp* app) {
    if(uhf_data_lock(app, 10)) {
        app->version[0] = '\0';
        uhf_data_unlock(app);
    }
}

static uint32_t uhf_read_be(const uint8_t* data, size_t len) {
    return uhf_protocol_read_be(data, len);
}

static bool uhf_bytes_to_hex(const uint8_t* data, size_t len, char* out, size_t out_size) {
    return uhf_protocol_bytes_to_hex(data, len, out, out_size);
}

static size_t uhf_format_hex_byte_groups(
    const char* hex,
    size_t hex_length,
    size_t byte_offset,
    size_t max_bytes,
    char* out,
    size_t out_size) {
    if(!hex || !out || out_size == 0U) return 0U;

    size_t written = 0U;
    size_t bytes = 0U;
    const size_t start = byte_offset * 2U;
    while(bytes < max_bytes && start + bytes * 2U + 1U < hex_length) {
        if(written && written + 1U < out_size) out[written++] = ' ';
        if(written + 2U >= out_size) break;
        out[written++] = hex[start + bytes * 2U];
        out[written++] = hex[start + bytes * 2U + 1U];
        bytes++;
    }
    out[written] = '\0';
    return bytes;
}

static void uhf_prune_stale_tags(UhfApp* app, uint32_t max_age_ms) {
    if(!app || !uhf_data_lock(app, 10)) return;

    const uint32_t now = furi_get_tick();
    size_t count = 0U;
    for(size_t i = 0U; i < UHF_MAX_TAGS; i++) {
        if(app->tags[i].used && (now - app->tags[i].last_seen) > max_age_ms) {
            memset(&app->tags[i], 0, sizeof(app->tags[i]));
        }
        if(app->tags[i].used) count++;
    }
    app->tag_count = count;
    uhf_data_unlock(app);
}

static bool uhf_is_valid_epc(const uint8_t* epc, size_t epc_len) {
    static const uint8_t reader_placeholder[] = {0xE2U, 0x80U, 0x69U, 0x00U, 0x00U};

    if(!epc || epc_len < 4U || epc_len > (UHF_EPC_HEX_MAX / 2U)) return false;

    /* All-zero EPCs are recoverable tags, not invalid frames. Keeping them
       visible lets the user assign a new EPC after an earlier clear. */
    return !(
        epc_len >= sizeof(reader_placeholder) &&
        memcmp(epc, reader_placeholder, sizeof(reader_placeholder)) == 0);
}

static UhfTagEntry* uhf_find_or_add_tag(UhfApp* app, const char* epc_hex, bool* is_new_tag) {
    const uint32_t now = furi_get_tick();

    for(size_t i = 0; i < UHF_MAX_TAGS; i++) {
        if(app->tags[i].used && strcmp(app->tags[i].epc, epc_hex) == 0) {
            /* Deduplicate: if this same EPC was seen very recently, don't count as new */
            const bool recent = (now - app->tags[i].last_seen) < 800U;
            if(is_new_tag) *is_new_tag = !recent;
            return &app->tags[i];
        }
    }

    for(size_t i = 0; i < UHF_MAX_TAGS; i++) {
        if(!app->tags[i].used) {
            app->tags[i].read_count = 0;
            app->tags[i].rssi = 0;
            app->tags[i].signal_bars = 0U;
            app->tags[i].signal_lower_since = 0U;
            app->tags[i].frequency = 0;
            app->tags[i].antenna = 0;
            strncpy(app->tags[i].epc, epc_hex, sizeof(app->tags[i].epc) - 1);
            app->tags[i].epc[sizeof(app->tags[i].epc) - 1] = '\0';
            app->tags[i].used = true;
            app->tags[i].last_seen = 0; /* will be set by caller */
            app->tag_count++;
            if(is_new_tag) *is_new_tag = true;
            return &app->tags[i];
        }
    }

    return NULL;
}

static bool uhf_build_frame(
    uint8_t cmd,
    const uint8_t* payload,
    size_t payload_len,
    uint8_t* out,
    size_t out_size,
    size_t* frame_size) {
    return uhf_protocol_build_ucm601_frame(cmd, payload, payload_len, out, out_size, frame_size);
}

static bool uhf_send_raw_frame(UhfApp* app, const uint8_t* frame, size_t frame_size) {
    if(!frame || frame_size < 5U) return false;
    if(!app->serial) return false;

    furi_hal_serial_tx(app->serial, frame, frame_size);
    furi_hal_serial_tx_wait_complete(app->serial);

    char hex[49] = "";
    const size_t shown = frame_size > 24U ? 24U : frame_size;
    if(uhf_bytes_to_hex(frame, shown, hex, sizeof(hex))) {
        uhf_diag_log(app, "TX len=%lu %s", (unsigned long)frame_size, hex);
        if(frame[3] == UHF_CMD_READ_TAG || frame[3] == UHF_CMD_WRITE_TAG ||
           frame[3] == UHF_CMD_LOCK_TAG || frame[3] == UHF_CMD_SET_EPC_MATCH) {
            FURI_LOG_I(TAG, "Tag TX %s", hex);
        }
    }

    return true;
}

static void uhf_store_last_rx_hex(UhfApp* app, const uint8_t* frame, size_t frame_size) {
    const size_t shown = frame_size > 20U ? 20U : frame_size;
    (void)uhf_bytes_to_hex(frame, shown, app->last_rx_hex, sizeof(app->last_rx_hex));
}

static bool
    uhf_send_command(UhfApp* app, uint8_t cmd, const uint8_t* payload, size_t payload_len) {
    uint8_t frame[272];
    size_t frame_size = 0;
    if(!uhf_build_frame(cmd, payload, payload_len, frame, sizeof(frame), &frame_size)) {
        return false;
    }

    return uhf_send_raw_frame(app, frame, frame_size);
}

static const char* uhf_tag_error_text(uint8_t code) {
    return uhf_protocol_tag_error_text(code);
}

static bool uhf_wait_tag_reply(
    UhfApp* app,
    uint8_t cmd,
    const uint8_t* payload,
    size_t payload_len,
    uint32_t timeout_ms) {
    app->tag_reply_ready = false;
    app->tag_reply_len = 0U;
    app->tag_reply_cmd = cmd;
    if(!uhf_send_command(app, cmd, payload, payload_len)) return false;

    const uint32_t started = furi_get_tick();
    while((furi_get_tick() - started) < timeout_ms) {
        uhf_process_rx(app);
        if(app->tag_reply_ready && app->tag_reply_cmd == cmd) {
            return app->tag_reply_checksum_ok;
        }
        furi_delay_ms(5U);
    }
    uhf_set_status(app, "Reader timeout (0x%02X)", cmd);
    return false;
}

static bool uhf_hex_to_bytes(const char* hex, uint8_t* out, size_t out_size, size_t* out_len) {
    return uhf_protocol_hex_to_bytes(hex, out, out_size, out_len);
}

static bool uhf_epc_hex_to_ascii(const char* epc_hex, char* out, size_t out_size) {
    return uhf_tag_epc_hex_to_ascii(epc_hex, out, out_size);
}

static char uhf_ascii_lower(char ch) {
    return (ch >= 'A' && ch <= 'Z') ? (char)(ch - 'A' + 'a') : ch;
}

static bool uhf_ascii_contains_ignore_case(const char* text, const char* needle) {
    if(!text || !needle || !needle[0]) return false;
    for(const char* start = text; *start; start++) {
        const char* a = start;
        const char* b = needle;
        while(*a && *b && uhf_ascii_lower(*a) == uhf_ascii_lower(*b)) {
            a++;
            b++;
        }
        if(!*b) return true;
    }
    return false;
}

static bool uhf_ascii_to_epc_hex(const char* ascii, char* out, size_t out_size) {
    return uhf_tag_ascii_to_epc_hex(ascii, out, out_size);
}

static bool uhf_set_selected_epc_filter(UhfApp* app) {
    uint8_t epc[UHF_EPC_HEX_MAX / 2U];
    size_t epc_len = 0U;
    if(!uhf_hex_to_bytes(app->access_epc, epc, sizeof(epc), &epc_len) || epc_len == 0U) {
        uhf_set_status(app, "Invalid selected EPC");
        return false;
    }

    uint8_t payload[2U + UHF_EPC_HEX_MAX / 2U];
    payload[0] = 0x00U;
    payload[1] = (uint8_t)epc_len;
    memcpy(&payload[2], epc, epc_len);
    if(!uhf_wait_tag_reply(app, UHF_CMD_SET_EPC_MATCH, payload, epc_len + 2U, 1200U)) {
        uhf_set_status(app, "EPC filter timeout");
        return false;
    }
    if(app->tag_reply_len != 1U || app->tag_reply[0] != 0x10U) {
        const uint8_t code = app->tag_reply_len ? app->tag_reply[0] : 0xFFU;
        uhf_set_status(app, "Filter error 0x%02X", code);
        return false;
    }
    app->epc_filter_active = true;
    return true;
}

static void uhf_clear_selected_epc_filter(UhfApp* app) {
    if(!app || !app->epc_filter_active) return;
    const uint8_t clear_mode = 0x01U;
    if(uhf_wait_tag_reply(app, UHF_CMD_SET_EPC_MATCH, &clear_mode, 1U, 600U) &&
       app->tag_reply_len == 1U && app->tag_reply[0] == 0x10U) {
        app->epc_filter_active = false;
    } else {
        uhf_set_status(app, "Clear EPC filter failed");
    }
}

static bool uhf_read_selected_bank_words(
    UhfApp* app,
    uint8_t memory_bank,
    uint8_t word_address,
    uint8_t word_count,
    char* out,
    size_t out_size,
    const char* name,
    bool use_epc_filter) {
    if(use_epc_filter && !app->epc_filter_active && !uhf_set_selected_epc_filter(app)) {
        return false;
    }

    out[0] = '\0';

    /* Newer UCM601NC firmware uses a 32-bit word address and 16-bit word count. */
    uint8_t payload[] = {
        memory_bank,
        0x00U,
        0x00U,
        0x00U,
        0x00U,
        0x00U,
        word_count,
        0x00U,
        0x00U,
        0x00U,
        0x00U,
    };
    payload[4] = word_address;
    memcpy(&payload[7], app->access_keys[app->active_key_slot], 4U);
    uhf_set_status(app, "Reading %s...", name);
    view_port_update(app->view_port);
    if(!uhf_wait_tag_reply(app, UHF_CMD_READ_TAG, payload, sizeof(payload), 2500U)) return false;
    if(app->tag_reply_len == 1U) {
        uhf_set_status(app, "%s", uhf_tag_error_text(app->tag_reply[0]));
        return false;
    }
    if(app->tag_reply_len < 6U) {
        uhf_set_status(app, "Malformed %s reply", name);
        return false;
    }

    const size_t record_len = app->tag_reply[2];
    const size_t record_end = 3U + record_len;
    if(record_end + 3U > app->tag_reply_len) {
        uhf_set_status(app, "Malformed %s record", name);
        return false;
    }
    size_t read_len = app->tag_reply[record_end];
    /* Extended firmware returns ReadLen as a 16-bit big-endian value. */
    if(record_end + 4U <= app->tag_reply_len) {
        const size_t extended_len = ((size_t)app->tag_reply[record_end] << 8U) |
                                    app->tag_reply[record_end + 1U];
        if(extended_len > 0U && extended_len <= record_len) read_len = extended_len;
    }
    if(read_len == 0U || (read_len & 1U) || read_len > (size_t)word_count * 2U ||
       read_len * 2U + 1U > out_size || read_len > record_len) {
        uhf_set_status(app, "Invalid %s length", name);
        return false;
    }
    const uint8_t* value = &app->tag_reply[record_end - read_len];
    if(!uhf_bytes_to_hex(value, read_len, out, out_size)) {
        uhf_set_status(app, "%s too long", name);
        return false;
    }
    uhf_set_status(app, "%s read: %lu bytes", name, (unsigned long)read_len);
    return true;
}

static bool uhf_read_selected_tid(UhfApp* app) {
    /* Six words covers the common 96-bit serialized TID. */
    app->selected_tid_valid = uhf_read_selected_bank_words(
        app,
        0x02U,
        0x00U,
        6U,
        app->selected_tid,
        sizeof(app->selected_tid),
        "TID",
        !app->tag_access_unfiltered);
    return app->selected_tid_valid;
}

static bool uhf_read_selected_user(UhfApp* app) {
    app->selected_user_valid = uhf_read_selected_bank_words(
        app,
        0x03U,
        0x00U,
        16U,
        app->selected_user,
        sizeof(app->selected_user),
        "USER",
        !app->tag_access_unfiltered);
    return app->selected_user_valid;
}

static const char* uhf_current_tag_bank_name(UhfTagBank bank) {
    return uhf_tag_bank_name(bank);
}

static UhfTagBank uhf_next_tag_bank(UhfTagBank bank) {
    if(bank == UhfTagBankEpc) return UhfTagBankTid;
    if(bank == UhfTagBankTid) return UhfTagBankUser;
    return UhfTagBankEpc;
}

static const char* uhf_current_tag_bank_button_name(UhfTagBank bank) {
    return uhf_tag_bank_button_name(bank);
}

static bool uhf_write_selected_bank_at(
    UhfApp* app,
    UhfTagBank bank,
    const char* value_hex,
    uint8_t word_address) {
    uint8_t value[UHF_USER_HEX_MAX / 2U];
    size_t value_len = 0U;
    const char* name = uhf_current_tag_bank_name(bank);
    if(!uhf_hex_to_bytes(value_hex, value, sizeof(value), &value_len) || !value_len ||
       (value_len & 1U)) {
        uhf_set_status(app, "%s must be whole words", name);
        uhf_notify_write_result(app, false);
        return false;
    }

    /* Normal tag actions stay EPC-filtered. Fuzzing explicitly opts into an
       unfiltered write because the source may be replaced by a target tag. */
    if(!app->tag_access_unfiltered && !app->epc_filter_active &&
       !uhf_set_selected_epc_filter(app)) {
        uhf_notify_write_result(app, false);
        return false;
    }
    if(app->tag_access_unfiltered) uhf_clear_selected_epc_filter(app);
    furi_delay_ms(UHF_STOP_SETTLE_MS);

    uint8_t payload[11U + UHF_USER_HEX_MAX / 2U] = {0};
    memcpy(payload, app->access_keys[app->active_key_slot], 4U);
    payload[4] = (bank == UhfTagBankEpc) ? 0x01U : (bank == UhfTagBankTid ? 0x02U : 0x03U);
    payload[8] = word_address;
    payload[10] = (uint8_t)(value_len / 2U);
    memcpy(&payload[11], value, value_len);
    uhf_set_status(app, "Writing %s...", name);
    if(!uhf_wait_tag_reply(app, UHF_CMD_WRITE_TAG, payload, 11U + value_len, 3000U)) {
        uhf_notify_write_result(app, false);
        return false;
    }

    uint8_t status = 0xFFU;
    if(app->tag_reply_len == 1U) {
        status = app->tag_reply[0];
    } else if(app->tag_reply_len >= 6U) {
        const size_t record_end = 3U + app->tag_reply[2];
        if(record_end < app->tag_reply_len) status = app->tag_reply[record_end];
    }
    if(status != 0x10U) {
        uhf_set_status(app, "%s write: %s", name, uhf_tag_error_text(status));
        uhf_notify_write_result(app, false);
        return false;
    }

    /* Once EPC memory changes, the old EPC filter can no longer match the
       same tag. Clear it before the verification read. */
    if(bank == UhfTagBankEpc) {
        uhf_clear_selected_epc_filter(app);
        if(!app->tag_access_unfiltered) {
            snprintf(app->access_epc, sizeof(app->access_epc), "%s", value_hex);
            if(!uhf_set_selected_epc_filter(app)) {
                uhf_set_status(app, "Write OK; filter failed");
                uhf_notify_write_result(app, false);
                return false;
            }
        }
    }

    char verify[UHF_USER_HEX_MAX + 1U] = "";
    if(!uhf_read_selected_bank_words(
           app,
           bank == UhfTagBankEpc ? 0x01U : (bank == UhfTagBankTid ? 0x02U : 0x03U),
           word_address,
           (uint8_t)(value_len / 2U),
           verify,
           sizeof(verify),
           name,
           false)) {
        uhf_set_status(app, "Write OK; verify failed");
        uhf_notify_write_result(app, false);
        return false;
    }
    if(strcmp(verify, value_hex) != 0) {
        uhf_set_status(app, "Verify mismatch");
        uhf_notify_write_result(app, false);
        return false;
    }
    if(bank == UhfTagBankEpc) {
        strncpy(app->selected_epc, verify, sizeof(app->selected_epc) - 1U);
        app->selected_epc[sizeof(app->selected_epc) - 1U] = '\0';
        strncpy(app->access_epc, verify, sizeof(app->access_epc) - 1U);
        app->access_epc[sizeof(app->access_epc) - 1U] = '\0';
    } else if(bank == UhfTagBankTid && word_address == 0U) {
        strncpy(app->selected_tid, verify, sizeof(app->selected_tid) - 1U);
        app->selected_tid[sizeof(app->selected_tid) - 1U] = '\0';
        app->selected_tid_valid = true;
    } else if(bank == UhfTagBankUser && word_address == 0U) {
        strncpy(app->selected_user, verify, sizeof(app->selected_user) - 1U);
        app->selected_user[sizeof(app->selected_user) - 1U] = '\0';
        app->selected_user_valid = true;
    }
    if(word_address > 0U && bank == UhfTagBankTid) app->selected_tid_valid = false;
    if(word_address > 0U && bank == UhfTagBankUser) app->selected_user_valid = false;
    uhf_set_status(app, "%s write verified", name);
    uhf_notify_write_result(app, true);
    return true;
}

static bool uhf_write_selected_bank(UhfApp* app, UhfTagBank bank, const char* value_hex) {
    return uhf_write_selected_bank_at(app, bank, value_hex, bank == UhfTagBankEpc ? 2U : 0U);
}

static uint8_t uhf_tag_reply_status(const UhfApp* app) {
    if(!app || app->tag_reply_len == 0U) return 0xFFU;
    if(app->tag_reply_len == 1U) return app->tag_reply[0];
    if(app->tag_reply_len >= 6U) {
        const size_t record_end = 3U + app->tag_reply[2];
        if(record_end < app->tag_reply_len) return app->tag_reply[record_end];
    }
    return 0xFFU;
}

static bool uhf_active_key_is_zero(const UhfApp* app) {
    const uint8_t* key = app->access_keys[app->active_key_slot];
    return !(key[0] || key[1] || key[2] || key[3]);
}

static bool uhf_lock_selected_bank(UhfApp* app, bool lock) {
    if(!app || !app->access_epc[0]) return false;
    if(lock && uhf_active_key_is_zero(app)) {
        uhf_set_status(app, "Set non-zero tag key first");
        uhf_notify_write_result(app, false);
        return false;
    }
    if(!app->epc_filter_active && !uhf_set_selected_epc_filter(app)) return false;

    uint8_t payload[6];
    memcpy(payload, app->access_keys[app->active_key_slot], 4U);
    payload[4] =
        app->tag_bank == UhfTagBankUser ? 0x01U : (app->tag_bank == UhfTagBankTid ? 0x02U : 0x03U);
    payload[5] = lock ? 0x01U : 0x00U;
    uhf_set_status(
        app, "%s %s...", lock ? "Locking" : "Unlocking", uhf_current_tag_bank_name(app->tag_bank));
    if(!uhf_wait_tag_reply(app, UHF_CMD_LOCK_TAG, payload, sizeof(payload), 3000U)) {
        uhf_notify_write_result(app, false);
        return false;
    }
    const uint8_t status = uhf_tag_reply_status(app);
    const bool ok = status == 0x10U;
    uhf_set_status(
        app, ok ? "%s complete" : "%s: %s", lock ? "Lock" : "Unlock", uhf_tag_error_text(status));
    uhf_notify_write_result(app, ok);
    return ok;
}

static bool uhf_initialize_tag_access_key(UhfApp* app) {
    if(!app || !app->access_epc[0]) return false;
    if(uhf_active_key_is_zero(app)) {
        uhf_set_status(app, "Select a non-zero key");
        return false;
    }
    if(!app->epc_filter_active && !uhf_set_selected_epc_filter(app)) return false;

    /* Recovery/initialization path for a tag whose current Access Password is
       zero. Reserved bank words 2-3 contain the new 32-bit Access Password. */
    uint8_t payload[15] = {0};
    payload[4] = 0x00U;
    payload[8] = 0x02U;
    payload[10] = 0x02U;
    memcpy(&payload[11], app->access_keys[app->active_key_slot], 4U);
    uhf_set_status(app, "Setting tag access key...");
    if(!uhf_wait_tag_reply(app, UHF_CMD_WRITE_TAG, payload, sizeof(payload), 3000U)) {
        uhf_notify_write_result(app, false);
        return false;
    }
    const uint8_t status = uhf_tag_reply_status(app);
    const bool ok = status == 0x10U;
    if(!ok) {
        uhf_set_status(app, "Set key: %s", uhf_tag_error_text(status));
        uhf_notify_write_result(app, false);
        return false;
    }

    char verify[9] = "";
    if(!uhf_read_selected_bank_words(
           app, 0x00U, 0x02U, 2U, verify, sizeof(verify), "Access key", true)) {
        uhf_set_status(app, "Key set; verify unavailable");
        uhf_notify_write_result(app, true);
        return true;
    }
    char expected[9];
    snprintf(
        expected,
        sizeof(expected),
        "%02X%02X%02X%02X",
        app->access_keys[app->active_key_slot][0],
        app->access_keys[app->active_key_slot][1],
        app->access_keys[app->active_key_slot][2],
        app->access_keys[app->active_key_slot][3]);
    const bool verified = strcmp(verify, expected) == 0;
    uhf_set_status(app, verified ? "Tag access key verified" : "Key set; verify mismatch");
    uhf_notify_write_result(app, verified);
    return verified;
}

static bool uhf_reset_tag_access_key(UhfApp* app) {
    if(!app || !app->access_epc[0]) return false;
    if(uhf_active_key_is_zero(app)) {
        uhf_set_status(app, "Select current non-zero key");
        uhf_notify_write_result(app, false);
        return false;
    }
    if(!app->epc_filter_active && !uhf_set_selected_epc_filter(app)) return false;

    /* Authenticate with the active key, then restore Reserved words 2-3 to
       the Gen2 default Access Password. Banks must be unlocked first. */
    uint8_t payload[15] = {0};
    memcpy(payload, app->access_keys[app->active_key_slot], 4U);
    payload[4] = 0x00U;
    payload[8] = 0x02U;
    payload[10] = 0x02U;
    uhf_set_status(app, "Resetting tag access key...");
    if(!uhf_wait_tag_reply(app, UHF_CMD_WRITE_TAG, payload, sizeof(payload), 3000U)) {
        uhf_notify_write_result(app, false);
        return false;
    }
    const uint8_t status = uhf_tag_reply_status(app);
    const bool ok = status == 0x10U;
    uhf_set_status(
        app, ok ? "Tag key reset to zero" : "Reset key: %s", uhf_tag_error_text(status));
    uhf_notify_write_result(app, ok);
    return ok;
}

static bool uhf_erase_selected_bank(UhfApp* app) {
    if(!app || app->tag_bank == UhfTagBankTid) {
        if(app) uhf_set_status(app, "TID cannot be erased");
        return false;
    }
    bool valid = false;
    const char* current = uhf_current_tag_bank_value(app, &valid);
    if(!valid || !current[0]) {
        uhf_set_status(app, "Read bank before erase");
        return false;
    }
    const size_t len = strlen(current);
    char zeros[UHF_USER_HEX_MAX + 1U];
    if(len > UHF_USER_HEX_MAX) return false;
    memset(zeros, '0', len);
    /* A completely zero EPC is legal on some tags but is commonly hidden by
       readers and makes multiple cleared tags indistinguishable. Preserve a
       minimal non-zero identity while clearing the rest of EPC memory. */
    if(app->tag_bank == UhfTagBankEpc && len > 0U) zeros[len - 1U] = '1';
    zeros[len] = '\0';
    return uhf_write_selected_bank(app, app->tag_bank, zeros);
}

static bool uhf_ensure_hardware(UhfApp* app) {
    /* hardware_ready means the UART is configured. Reader presence is tracked
       independently by the version response. */
    if(app->hardware_ready && app->serial) return true;

    const uint32_t desired_baud = app->baud_rate;

    if(!app->serial) {
        uhf_force_direct_a6_a4(app);
    }
    if(!app->serial) {
        uhf_set_status(app, "UART 13/14 open failed");
        return false;
    }

    app->hardware_ready = true;

    bool probe_ok = false;
    if(desired_baud != 0U) {
        probe_ok = uhf_probe_current_serial(app, desired_baud);
    }
    if(!probe_ok) {
        probe_ok = uhf_probe_current_serial(app, UHF_BAUD_RATE);
    }

    uhf_diag_log(
        app,
        "HW ready TX:%d RX:%d probe=%s",
        app->tx_ext_pin,
        app->rx_ext_pin,
        probe_ok ? "ok" : "fail");
    return true;
}

static void uhf_apply_baud(UhfApp* app, uint32_t baud_rate) {
    app->baud_rate = baud_rate;
    if(!app->serial) return;

    if(app->inventory_running) {
        app->inventory_running = false;
        (void)uhf_send_command(app, UHF_CMD_STOP_INV, NULL, 0);
    }

    furi_hal_serial_async_rx_stop(app->serial);
    furi_hal_serial_set_br(app->serial, baud_rate);
    furi_hal_serial_async_rx_start(app->serial, uhf_on_rx_irq, app, true);

    app->frame_buffer_len = 0;
    if(app->rx_stream) {
        (void)furi_stream_buffer_reset(app->rx_stream);
    }
    uhf_set_status(app, "Baud: %lu", (unsigned long)baud_rate);
}
static void uhf_stop_inventory(UhfApp* app) {
    static const uint8_t stop_frame[] = {0xA0, 0x03, 0x00, 0x8C, 0xD1};
    app->inventory_running = false;
    app->tags_per_second = 0;
    app->rate_window_reads = 0;
    app->rate_window_started = furi_get_tick();
    app->radar_step_tick = furi_get_tick();
    app->last_inv_session_tick = 0U;
    if(app->hardware_ready) {
        (void)uhf_send_raw_frame(app, stop_frame, sizeof(stop_frame));
    }
}

static bool uhf_wait_for_reader_query(UhfApp* app, bool* pending) {
    const uint32_t started = furi_get_tick();
    while(*pending && (furi_get_tick() - started) < UHF_READER_QUERY_TIMEOUT_MS) {
        uhf_process_rx(app);
        if(*pending) furi_delay_ms(5U);
    }

    if(*pending) {
        *pending = false;
        return false;
    }
    return true;
}

static bool uhf_query_reader_temperature(UhfApp* app, bool wait_for_response) {
    app->temperature_query_pending = true;
    if(!uhf_send_command(app, UHF_CMD_GET_TEMP, NULL, 0U)) {
        app->temperature_query_pending = false;
        return false;
    }

    app->last_temperature_query_tick = furi_get_tick();
    return !wait_for_response || uhf_wait_for_reader_query(app, &app->temperature_query_pending);
}

static bool uhf_query_reader_power(UhfApp* app, bool wait_for_response) {
    app->power_query_pending = true;
    if(!uhf_send_command(app, UHF_CMD_GET_POWER, NULL, 0U)) {
        app->power_query_pending = false;
        return false;
    }

    return !wait_for_response || uhf_wait_for_reader_query(app, &app->power_query_pending);
}

static bool uhf_set_reader_power(UhfApp* app, uint8_t power_dbm) {
    if(!app || power_dbm > 20U || !uhf_ensure_hardware(app)) return false;
    if(app->inventory_running) uhf_stop_inventory(app);

    if(!uhf_wait_tag_reply(app, UHF_CMD_SET_POWER, &power_dbm, 1U, 1000U)) {
        uhf_set_status(app, "Power command timeout");
        return false;
    }

    /* UCM601 replies with 0x10 on success. Some firmware echoes the value. */
    if(app->tag_reply_len == 0U ||
       (app->tag_reply[0] != 0x10U && app->tag_reply[0] != power_dbm)) {
        uhf_set_status(app, "Power set failed");
        return false;
    }
    app->reader_power_dbm = power_dbm;
    app->power_valid = true;
    uhf_set_status(app, "RF power: %u dBm", power_dbm);
    return true;
}

static bool uhf_save_reader_params(UhfApp* app) {
    if(!uhf_ensure_hardware(app)) return false;
    if(!uhf_wait_tag_reply(app, UHF_CMD_SAVE_PARAMS, NULL, 0U, 1200U)) return false;
    return app->tag_reply_len == 1U && app->tag_reply[0] == 0x10U;
}

static bool uhf_set_reader_buzzer(UhfApp* app) {
    if(!uhf_ensure_hardware(app)) return false;
    const uint8_t enabled = app->reader_buzzer_enabled ? 1U : 0U;
    return uhf_wait_tag_reply(app, UHF_CMD_SET_BUZZER, &enabled, 1U, 1200U) &&
           app->tag_reply_len == 1U && app->tag_reply[0] == 0x10U;
}

static bool uhf_query_reader_uuid(UhfApp* app) {
    app->reader_uuid_valid = false;
    if(!uhf_ensure_hardware(app) || !uhf_wait_tag_reply(app, UHF_CMD_GET_UUID, NULL, 0U, 1200U) ||
       app->tag_reply_len != 16U)
        return false;
    app->reader_uuid_valid =
        uhf_protocol_bytes_to_hex(app->tag_reply, 16U, app->reader_uuid, sizeof(app->reader_uuid));
    return app->reader_uuid_valid;
}

static void uhf_refresh_about_reader(UhfApp* app) {
    uhf_request_version(app);
    (void)uhf_query_reader_temperature(app, true);
    (void)uhf_query_reader_power(app, true);
    (void)uhf_query_reader_uuid(app);
}

static bool uhf_reset_reader_command(UhfApp* app) {
    if(!uhf_ensure_hardware(app)) return false;
    if(app->inventory_running) uhf_stop_inventory(app);
    if(!uhf_wait_tag_reply(app, UHF_CMD_RESET, NULL, 0U, 1200U) || app->tag_reply_len != 1U ||
       app->tag_reply[0] != 0x10U)
        return false;
    furi_delay_ms(UHF_RESET_SETTLE_MS);
    uhf_clear_version(app);
    return uhf_try_reader_handshake(app, 3U);
}

static void uhf_start_inventory(UhfApp* app) {
    static const uint8_t start_frame[] = {0xA0, 0x04, 0x00, 0x89, 0x01, 0xD2};
    if(!uhf_ensure_hardware(app)) return;

    if(!uhf_has_version(app)) {
        uhf_set_status(app, "Connecting reader...");
        bool reader_ok = uhf_try_reader_handshake(app, 2U);
        if(!reader_ok && uhf_recover_reader(app)) {
            reader_ok = uhf_try_reader_handshake(app, 5U);
        }
        if(!reader_ok) {
            uhf_set_status(app, "Not Ready");
            return;
        }
    }

    /* Read reader telemetry while RF inventory is idle so the replies cannot
       compete with a burst of tag reports. A missing reply does not prevent
       inventory from starting; the radar keeps the last valid value. */
    (void)uhf_query_reader_temperature(app, true);
    (void)uhf_query_reader_power(app, true);

    (void)furi_stream_buffer_reset(app->rx_stream);
    app->frame_buffer_len = 0;
    const bool sent = uhf_send_raw_frame(app, start_frame, sizeof(start_frame));
    uhf_process_rx(app);

    if(sent) {
        app->inventory_running = true;
        app->tags_per_second = 0;
        app->rate_window_reads = 0;
        app->rate_window_started = furi_get_tick();
        app->radar_step_tick = furi_get_tick();
        app->last_inv_refresh_tick = furi_get_tick();
        app->last_inv_session_tick = app->last_inv_refresh_tick;
        uhf_set_status(app, "Inventory running");
    } else {
        uhf_set_status(app, "Start inventory failed");
    }
}

static bool uhf_try_reader_handshake(UhfApp* app, uint8_t attempts) {
    if(!app || attempts == 0U) return false;

    for(uint8_t attempt = 0U; attempt < attempts; attempt++) {
        uhf_request_version(app);
        if(uhf_wait_for_version(app, UHF_PROBE_TIMEOUT_MS)) {
            app->baud_probed = true;
            return true;
        }
    }
    return false;
}

static bool uhf_recover_reader(UhfApp* app) {
    if(!app || !app->serial) return false;

    uhf_stop_inventory(app);
    furi_delay_ms(UHF_STOP_SETTLE_MS);
    if(app->rx_stream) furi_stream_buffer_reset(app->rx_stream);
    app->frame_buffer_len = 0U;

    static const uint8_t reset_frame[] = {0xA0, 0x03, 0x00, UHF_CMD_RESET, 0xED};
    if(!uhf_send_raw_frame(app, reset_frame, sizeof(reset_frame))) return false;

    uhf_diag_log(app, "Reader reset sent");
    furi_delay_ms(UHF_RESET_SETTLE_MS);
    uhf_process_rx(app);
    if(app->rx_stream) furi_stream_buffer_reset(app->rx_stream);
    app->frame_buffer_len = 0U;
    uhf_clear_version(app);
    return true;
}

static void uhf_release_reset_pin(void) {
    furi_hal_gpio_init_simple(&gpio_ext_pc0, GpioModeAnalog);
}

static void uhf_hardware_reset_reader(UhfApp* app) {
    /* Hardware revision 2 connects UCM601NC RST (active low) to Flipper C0,
       external header pin 16. Keep it driven high after the pulse so the
       reader cannot drift back into reset. On revision 1 C0 is unconnected,
       making this sequence harmless. */
    furi_hal_gpio_write(&gpio_ext_pc0, true);
    furi_hal_gpio_init_simple(&gpio_ext_pc0, GpioModeOutputPushPull);
    furi_delay_ms(2U);
    furi_hal_gpio_write(&gpio_ext_pc0, false);
    furi_delay_ms(UHF_RESET_LOW_MS);
    furi_hal_gpio_write(&gpio_ext_pc0, true);
    furi_delay_ms(UHF_RESET_BOOT_MS);
    if(app) {
        uhf_diag_log(app, "Hardware reset C0/pin %u", (unsigned)UHF_RESET_EXT_PIN);
    }
}

static bool uhf_power_cycle_reader(UhfApp* app) {
    if(!app || app->hard_reset_attempted) return false;
    app->hard_reset_attempted = true;

    if(app->serial) uhf_close_serial(app);
    app->hardware_ready = false;

    Storage* storage = furi_record_open(RECORD_STORAGE);
    if(!storage) {
        uhf_diag_log(app, "Hard reset: storage unavailable");
        return false;
    }

    const FS_Error unmount_error = storage_sd_unmount(storage);
    if(unmount_error != FSE_OK && unmount_error != FSE_NOT_READY) {
        uhf_diag_log(app, "Hard reset: SD unmount failed %d", (int)unmount_error);
        furi_record_close(RECORD_STORAGE);
        return false;
    }

    /* Put both UART lines low before the supply falls, keep them low while the
       reader is unpowered, and hold them low throughout its next power-up. */
    furi_hal_gpio_write(&gpio_usart_tx, false);
    furi_hal_gpio_write(&gpio_usart_rx, false);
    furi_hal_gpio_init_simple(&gpio_usart_tx, GpioModeOutputPushPull);
    furi_hal_gpio_init_simple(&gpio_usart_rx, GpioModeOutputPushPull);

    uhf_diag_log(app, "Hard reset: UART low, external 3.3V off");
    furi_hal_power_disable_external_3_3v();
    furi_delay_ms(UHF_POWER_OFF_MS);

    furi_hal_power_enable_external_3_3v();

    FS_Error mount_error = FSE_NOT_READY;
    uint32_t power_boot_elapsed_ms = 0U;
    for(uint8_t attempt = 0U; attempt < 8U && mount_error != FSE_OK; attempt++) {
        furi_delay_ms(100U);
        power_boot_elapsed_ms += 100U;
        mount_error = storage_sd_mount(storage);
    }

    if(UHF_POWER_BOOT_MS > power_boot_elapsed_ms) {
        furi_delay_ms(UHF_POWER_BOOT_MS - power_boot_elapsed_ms);
    }

    furi_hal_gpio_init_simple(&gpio_usart_tx, GpioModeAnalog);
    furi_hal_gpio_init_simple(&gpio_usart_rx, GpioModeAnalog);
    furi_delay_ms(UHF_POWER_READY_MS);
    furi_record_close(RECORD_STORAGE);

    if(mount_error != FSE_OK) {
        uhf_diag_log(app, "Hard reset: SD mount failed %d", (int)mount_error);
        return false;
    }

    app->baud_rate = UHF_BAUD_RATE;
    if(!uhf_open_bridge_uart(app)) {
        uhf_diag_log(app, "Hard reset: UART reopen failed");
        return false;
    }

    app->hardware_ready = true;
    uhf_hardware_reset_reader(app);
    app->frame_buffer_len = 0U;
    if(app->rx_stream) furi_stream_buffer_reset(app->rx_stream);
    uhf_clear_version(app);
    uhf_diag_log(app, "Hard reset complete");
    return true;
}

static void uhf_service_inventory(UhfApp* app) {
    if(!app || !app->inventory_running) return;

    const uint32_t now = furi_get_tick();
    if(app->temperature_query_pending &&
       (now - app->last_temperature_query_tick) >= UHF_READER_QUERY_TIMEOUT_MS) {
        app->temperature_query_pending = false;
        uhf_diag_log(app, "Temperature query timeout");
    }
    if(!app->temperature_query_pending &&
       (now - app->last_temperature_query_tick) >= UHF_TEMP_REFRESH_MS) {
        (void)uhf_query_reader_temperature(app, false);
        return;
    }

    const bool session_renew_due = (now - app->last_inv_session_tick) >= UHF_INV_SESSION_RENEW_MS;
    if(session_renew_due) {
        static const uint8_t stop_frame[] = {0xA0, 0x03, 0x00, 0x8C, 0xD1};
        static const uint8_t start_frame[] = {0xA0, 0x04, 0x00, 0x89, 0x01, 0xD2};

        (void)uhf_send_raw_frame(app, stop_frame, sizeof(stop_frame));
        furi_delay_ms(UHF_INV_RENEW_SETTLE_MS);
        uhf_process_rx(app);

        const uint32_t restarted_at = furi_get_tick();
        if(uhf_send_raw_frame(app, start_frame, sizeof(start_frame))) {
            app->last_inv_refresh_tick = restarted_at;
            app->last_inv_session_tick = restarted_at;
            uhf_set_status(app, "Inventory running");
            uhf_diag_log(app, "Inventory session renewed");
        } else {
            app->last_inv_session_tick = restarted_at;
            uhf_set_status(app, "Inventory restart failed");
        }
        return;
    }

    const bool heartbeat_due = (now - app->last_inv_refresh_tick) >= UHF_INV_HEARTBEAT_MS;
    if(!heartbeat_due) return;

    /* The reader's completion response is not a reliable pacing signal and
       immediately chaining on it can overrun the reader. Match the proven
       Cardputer cadence: start one repeat every 250 ms without inserting a
       stop command or clearing buffered reports between rounds. */
    static const uint8_t start_frame[] = {0xA0, 0x04, 0x00, 0x89, 0x01, 0xD2};

    if(uhf_send_raw_frame(app, start_frame, sizeof(start_frame))) {
        app->last_inv_refresh_tick = now;
        uhf_set_status(app, "Inventory running");
    } else {
        app->last_inv_refresh_tick = now;
        uhf_set_status(app, "Inventory restart failed");
    }
}

static void uhf_request_version(UhfApp* app) {
    if(!uhf_ensure_hardware(app)) return;
    app->frame_buffer_len = 0;
    app->rx_bytes = 0;
    app->rx_frames = 0;
    app->rx_errors = 0;
    app->last_rx_hex[0] = '\0';
    uhf_clear_version(app);
    if(app->rx_stream) {
        (void)furi_stream_buffer_reset(app->rx_stream);
    }

    static const uint8_t version_frame[] = {0xA0, 0x03, 0x00, 0x72, 0xEB};
    bool sent = false;
    for(size_t attempt = 0; attempt < 2; attempt++) {
        if(uhf_send_raw_frame(app, version_frame, sizeof(version_frame))) {
            sent = true;
        }
        uhf_process_rx(app);
        furi_delay_ms(8);
    }

    if(sent) {
        uhf_set_status(app, "Version checking...");
        uhf_diag_log(app, "Version req TX:%d RX:%d", app->tx_ext_pin, app->rx_ext_pin);
    } else {
        uhf_set_status(app, "Version tx failed");
        uhf_diag_log(app, "Version tx failed");
    }
}

static bool uhf_add_inventory_tag(
    UhfApp* app,
    const uint8_t* epc,
    size_t epc_len,
    uint8_t antenna,
    uint32_t rssi,
    uint32_t frequency,
    uint32_t hit_count,
    uint16_t pc) {
    if(!uhf_is_valid_epc(epc, epc_len)) return false;
    if(hit_count == 0U) hit_count = 1U;

    char epc_hex[UHF_EPC_HEX_MAX + 1];
    if(!uhf_bytes_to_hex(epc, epc_len, epc_hex, sizeof(epc_hex))) return false;

    if(uhf_capture_saved_write_report(app, epc_hex, pc, rssi)) return true;
    if(app->ascii_filter_active) {
        char ascii[UHF_EPC_HEX_MAX / 2U + 1U];
        if(!uhf_epc_hex_to_ascii(epc_hex, ascii, sizeof(ascii)) ||
           !uhf_ascii_contains_ignore_case(ascii, app->ascii_filter))
            return true;
    }
    bool is_new_tag = false;
    if(!uhf_data_lock(app, 10)) return false;

    UhfTagEntry* tag = uhf_find_or_add_tag(app, epc_hex, &is_new_tag);
    if(!tag) {
        uhf_data_unlock(app);
        uhf_set_status(app, "Tag cache full");
        return false;
    }

    const uint32_t updated_count = (uint32_t)tag->read_count + hit_count;
    tag->read_count = updated_count > UINT16_MAX ? UINT16_MAX : (uint16_t)updated_count;
    app->rate_window_reads += hit_count;
    const uint32_t now = furi_get_tick();
    const uint8_t current_bars = uhf_signal_bar_level(rssi, epc_len);
    if(!tag->last_seen || now - tag->last_seen > UHF_SIGNAL_FRESH_MS) {
        tag->signal_bars = current_bars;
        tag->signal_lower_since = 0U;
    } else if(current_bars >= tag->signal_bars) {
        tag->signal_bars = current_bars;
        tag->signal_lower_since = 0U;
    } else if(!tag->signal_lower_since) {
        tag->signal_lower_since = now;
    } else if(now - tag->signal_lower_since >= UHF_SIGNAL_DROP_HOLD_MS) {
        tag->signal_bars--;
        tag->signal_lower_since = now;
    }
    tag->last_seen = now;
    tag->antenna = antenna;
    tag->rssi = rssi;
    tag->frequency = frequency;
    tag->pc = pc;
    uhf_data_unlock(app);

    uhf_notify_tag_found(app);

    if(is_new_tag) {
        const size_t total = uhf_count_tags(app);
        if(!app->list_selection_manual) {
            app->list_top_index = 0U;
            app->list_selected_index = 0U;
        }
        uhf_set_status(app, "Tag Found: %lu", (unsigned long)total);
    }

    return true;
}

static bool uhf_parse_pc_epc_at(
    UhfApp* app,
    const uint8_t* data,
    size_t data_len,
    size_t pc_offset,
    uint8_t antenna) {
    if(data_len < pc_offset + 4U) return false;

    const uint16_t pc = (uint16_t)((data[pc_offset] << 8) | data[pc_offset + 1U]);
    const size_t epc_words = (pc >> 11) & 0x1F;
    const size_t epc_len = epc_words * 2U;
    const size_t epc_offset = pc_offset + 2U;
    const size_t meta_offset = epc_offset + epc_len;

    if(epc_len == 0 || epc_len > (UHF_EPC_HEX_MAX / 2U) || data_len < meta_offset) return false;

    uint32_t rssi = 0;
    uint32_t frequency = 0;
    if(data_len >= meta_offset + 7U) {
        rssi = uhf_read_be(&data[meta_offset], 4);
        frequency = uhf_read_be(&data[meta_offset + 4U], 3);
    }

    return uhf_add_inventory_tag(
        app, &data[epc_offset], epc_len, antenna, rssi, frequency, 1U, pc);
}

static bool uhf_parse_inventory_buffer_frame(UhfApp* app, const uint8_t* data, size_t data_len) {
    if(data_len < 11U) return false;

    const size_t inv_data_len = data[0];
    const size_t required_len = 1U + inv_data_len + 4U + 3U + 1U + 1U;
    if(inv_data_len < 4U || data_len < required_len) return false;

    const uint8_t* inv_data = &data[1];
    const size_t epc_len = inv_data_len - 4U;
    const size_t offset = 1U + inv_data_len;
    const uint8_t antenna = data[offset + 7U];
    uint32_t hit_count = data[offset + 8U];
    if(hit_count == 0U) hit_count = 1U;
    const uint32_t rssi = uhf_read_be(&data[offset], 4);
    const uint32_t frequency = uhf_read_be(&data[offset + 4U], 3);

    return uhf_add_inventory_tag(
        app,
        &inv_data[2],
        epc_len,
        antenna,
        rssi,
        frequency,
        hit_count,
        (uint16_t)((inv_data[0] << 8U) | inv_data[1]));
}

static bool
    uhf_parse_inventory_frame(UhfApp* app, const uint8_t* data, size_t data_len, uint8_t cmd) {
    if(cmd == UHF_CMD_INV_ALT && uhf_parse_inventory_buffer_frame(app, data, data_len)) {
        return true;
    }
    if(uhf_parse_pc_epc_at(app, data, data_len, 1U, data_len ? data[0] : 0U)) return true;
    if(cmd != UHF_CMD_INV_ALT && uhf_parse_inventory_buffer_frame(app, data, data_len)) {
        return true;
    }

    for(size_t offset = 0; offset < 3U && offset < data_len; offset++) {
        if(uhf_parse_pc_epc_at(app, data, data_len, offset, 0)) return true;
    }

    return false;
}

static void uhf_handle_frame(UhfApp* app, const uint8_t* frame, size_t frame_size) {
    if(frame_size < 5U || frame[0] != UHF_FRAME_START) return;

    uhf_store_last_rx_hex(app, frame, frame_size);

    uint8_t checksum_acc = 0;
    for(size_t i = 0; i < frame_size; i++) {
        checksum_acc = (uint8_t)(checksum_acc + frame[i]);
    }
    if(checksum_acc != 0U) {
        app->rx_errors++;
    }

    app->rx_frames++;

    const uint8_t cmd = frame[3];
    const size_t data_len = (frame[1] >= 3U) ? (size_t)(frame[1] - 3U) : 0U;
    const uint8_t* data = &frame[4];

    uhf_diag_log(
        app,
        "RX cmd=%02X len=%lu cs=%s",
        cmd,
        (unsigned long)data_len,
        (checksum_acc == 0U) ? "ok" : "bad");

    if(cmd == UHF_CMD_READ_TAG || cmd == UHF_CMD_WRITE_TAG || cmd == UHF_CMD_LOCK_TAG ||
       cmd == UHF_CMD_SET_EPC_MATCH || cmd == UHF_CMD_SET_POWER || cmd == UHF_CMD_SAVE_PARAMS ||
       cmd == UHF_CMD_SET_BUZZER || cmd == UHF_CMD_RESET || cmd == UHF_CMD_GET_UUID) {
        FURI_LOG_I(
            TAG,
            "Tag RX cmd=%02X len=%lu cs=%s raw=%s",
            cmd,
            (unsigned long)data_len,
            checksum_acc == 0U ? "ok" : "bad",
            app->last_rx_hex);
    }

    if(cmd == UHF_CMD_READ_TAG || cmd == UHF_CMD_WRITE_TAG || cmd == UHF_CMD_LOCK_TAG ||
       cmd == UHF_CMD_SET_EPC_MATCH || cmd == UHF_CMD_SET_POWER || cmd == UHF_CMD_SAVE_PARAMS ||
       cmd == UHF_CMD_SET_BUZZER || cmd == UHF_CMD_RESET || cmd == UHF_CMD_GET_UUID) {
        const size_t copied = data_len > sizeof(app->tag_reply) ? sizeof(app->tag_reply) :
                                                                  data_len;
        if(copied) memcpy(app->tag_reply, data, copied);
        app->tag_reply_len = copied;
        app->tag_reply_cmd = cmd;
        app->tag_reply_checksum_ok = checksum_acc == 0U;
        app->tag_reply_ready = true;
        return;
    }

    if(cmd == UHF_CMD_GET_VERSION && data_len >= 3U) {
        if(uhf_data_lock(app, 10)) {
            snprintf(app->version, sizeof(app->version), "%u.%u.%u", data[0], data[1], data[2]);
            uhf_data_unlock(app);
        }
        uhf_set_status(app, "Version %s", app->version);
        uhf_diag_log(app, "Version=%s", app->version);
    } else if(cmd == UHF_CMD_GET_TEMP) {
        app->temperature_query_pending = false;
        FURI_LOG_I(
            TAG,
            "Temperature response: len=%lu sign=%u value=%u checksum=%s",
            (unsigned long)data_len,
            data_len >= 1U ? data[0] : 0U,
            data_len >= 2U ? data[1] : 0U,
            checksum_acc == 0U ? "ok" : "bad");
        if(checksum_acc == 0U && data_len >= 2U && data[0] <= 1U) {
            int16_t raw_temperature = (int16_t)data[1];
            if(data[0] == 0U) raw_temperature = -raw_temperature;
            if(uhf_data_lock(app, 10)) {
                app->reader_temperature_c = raw_temperature;
                app->temperature_valid = true;
                uhf_data_unlock(app);
            }
            uhf_diag_log(app, "Temperature=%dC", (int)raw_temperature);
            FURI_LOG_I(TAG, "Reader temperature: %d C", (int)raw_temperature);
        } else {
            uhf_diag_log(app, "Temperature query failed");
            FURI_LOG_W(TAG, "Reader temperature query failed");
        }
    } else if(cmd == UHF_CMD_GET_POWER) {
        app->power_query_pending = false;
        if(checksum_acc == 0U && data_len >= 1U && data[0] <= 33U) {
            if(uhf_data_lock(app, 10)) {
                /* This expansion uses antenna 1; multi-antenna readers return
                   additional power bytes after the first one. */
                app->reader_power_dbm = data[0];
                app->power_valid = true;
                uhf_data_unlock(app);
            }
            uhf_diag_log(app, "Power=%udBm", data[0]);
            FURI_LOG_I(TAG, "Reader output power: %u dBm", data[0]);
        } else {
            uhf_diag_log(app, "Power query failed");
            FURI_LOG_W(TAG, "Reader output power query failed");
        }
    } else if(cmd == UHF_CMD_START_INV || cmd == UHF_CMD_INV_ALT || app->inventory_running) {
        const bool parsed_tag = uhf_parse_inventory_frame(app, data, data_len, cmd);
        if(!parsed_tag && checksum_acc == 0U &&
           (cmd == UHF_CMD_START_INV || cmd == UHF_CMD_INV_ALT) && data_len <= 7U) {
            /* A short 0x89/0x8A reply is completion/error status, not tag data.
               The fixed inventory heartbeat starts the next round. */
            uhf_diag_log(app, "Inventory ended cmd=%02X len=%lu", cmd, (unsigned long)data_len);
        }
    } else if(cmd == UHF_CMD_STOP_INV) {
        if(!app->inventory_running) {
            uhf_set_status(app, "Inventory stopped");
        }
    }
}

static void uhf_process_rx(UhfApp* app) {
    uint8_t chunk[64];
    size_t got = 0;
    size_t chunk_budget = UHF_RX_CHUNKS_PER_PASS;
    size_t frame_budget = UHF_RX_FRAMES_PER_PASS;

    while(chunk_budget && frame_budget &&
          (got = furi_stream_buffer_receive(app->rx_stream, chunk, sizeof(chunk), 0)) > 0U) {
        chunk_budget--;
        app->rx_bytes += got;
        if(app->frame_buffer_len + got > sizeof(app->frame_buffer)) {
            app->rx_errors++;
            app->frame_buffer_len = 0;
        }

        memcpy(&app->frame_buffer[app->frame_buffer_len], chunk, got);
        app->frame_buffer_len += got;

        size_t index = 0;
        while(index < app->frame_buffer_len) {
            while(index < app->frame_buffer_len && app->frame_buffer[index] != UHF_FRAME_START) {
                index++;
            }
            if((app->frame_buffer_len - index) < 2U) break;

            const size_t frame_size = (size_t)app->frame_buffer[index + 1U] + 2U;
            if(frame_size < 5U) {
                app->rx_errors++;
                index++;
                continue;
            }
            if((app->frame_buffer_len - index) < frame_size) break;

            uhf_handle_frame(app, &app->frame_buffer[index], frame_size);
            index += frame_size;

            frame_budget--;
            if(frame_budget == 0U) {
                break;
            }
        }

        if(index > 0U) {
            const size_t remain = app->frame_buffer_len - index;
            if(remain) {
                memmove(app->frame_buffer, &app->frame_buffer[index], remain);
            }
            app->frame_buffer_len = remain;
        }

        if(frame_budget == 0U) {
            break;
        }
    }
}

static bool uhf_wait_for_version(UhfApp* app, uint32_t timeout_ms) {
    const uint32_t started = furi_get_tick();
    while((furi_get_tick() - started) < timeout_ms) {
        uhf_process_rx(app);
        if(uhf_has_version(app)) {
            return true;
        }
        furi_delay_ms(12U);
    }
    return false;
}

static bool uhf_probe_current_serial(UhfApp* app, uint32_t baud) {
    if(!app->serial) return false;

    uhf_apply_baud(app, baud);
    uhf_clear_version(app);
    if(!uhf_has_version(app)) {
        uhf_request_version(app);
    }
    return uhf_wait_for_version(app, UHF_PROBE_TIMEOUT_MS);
}

static bool uhf_save_diag_log(UhfApp* app) {
    Storage* storage = furi_record_open(RECORD_STORAGE);
    if(!storage) {
        uhf_set_status(app, "Storage unavailable");
        return false;
    }

    if(!storage_dir_exists(storage, UHF_APP_DATA_DIR)) {
        const FS_Error mkdir_result = storage_common_mkdir(storage, UHF_APP_DATA_DIR);
        if(mkdir_result != FSE_OK && mkdir_result != FSE_EXIST) {
            furi_record_close(RECORD_STORAGE);
            uhf_set_status(app, "Create dir failed");
            return false;
        }
    }

    char path[128];
    const uint32_t now = furi_get_tick();
    snprintf(path, sizeof(path), UHF_APP_DATA_DIR "/diag_%lu.log", (unsigned long)now);

    File* file = storage_file_alloc(storage);
    if(!file) {
        furi_record_close(RECORD_STORAGE);
        uhf_set_status(app, "File alloc failed");
        return false;
    }

    bool ok = false;
    do {
        if(!storage_file_open(file, path, FSAM_WRITE, FSOM_CREATE_ALWAYS)) {
            uhf_set_status(app, "Open log failed");
            break;
        }

        char header[128];
        const int header_len = snprintf(
            header,
            sizeof(header),
            "diag tick=%lu tx=%d rx=%d baud=%lu\\n",
            (unsigned long)now,
            app->tx_ext_pin,
            app->rx_ext_pin,
            (unsigned long)app->baud_rate);
        if(header_len > 0) {
            (void)storage_file_write(file, header, (size_t)header_len);
        }

        const size_t count = app->diag_count;
        const size_t start = (app->diag_head + UHF_DIAG_LOG_LINES - count) % UHF_DIAG_LOG_LINES;
        for(size_t i = 0; i < count; i++) {
            const size_t idx = (start + i) % UHF_DIAG_LOG_LINES;
            const char* line = app->diag_log[idx];
            if(!line[0]) continue;
            const size_t len = strlen(line);
            if(len) {
                (void)storage_file_write(file, line, len);
                (void)storage_file_write(file, "\\n", 1);
            }

            // Yield periodically to keep UI/task scheduler responsive on long writes.
            if((i & 0x07U) == 0x07U) {
                furi_delay_ms(1);
            }
        }

        storage_file_sync(file);
        uhf_set_status(app, "Diag saved: %s", path);
        ok = true;
    } while(false);

    storage_file_close(file);
    storage_file_free(file);
    furi_record_close(RECORD_STORAGE);
    return ok;
}

static void uhf_clear_tags(UhfApp* app) {
    if(uhf_data_lock(app, 10)) {
        memset(app->tags, 0, sizeof(app->tags));
        app->tag_count = 0;
        app->list_top_index = 0;
        app->list_selected_index = 0;
        app->list_selection_manual = false;
        uhf_data_unlock(app);
    }
    uhf_set_status(app, "Records cleared");
}

static void uhf_update_inventory_rate(UhfApp* app) {
    if(!app) return;

    const uint32_t now = furi_get_tick();
    if(app->rate_window_started == 0U) {
        app->rate_window_started = now;
        return;
    }

    const uint32_t elapsed = now - app->rate_window_started;
    if(elapsed < 1000U) return;

    if(uhf_data_lock(app, 10)) {
        app->tags_per_second =
            app->inventory_running ?
                (uint32_t)(((uint64_t)app->rate_window_reads * 1000U) / elapsed) :
                0U;
        app->rate_window_reads = 0U;
        app->rate_window_started = now;
        uhf_data_unlock(app);
    }
}

static void uhf_update_radar_animation(UhfApp* app) {
    if(!app) return;

    const uint32_t now = furi_get_tick();
    if(!app->inventory_running) {
        /* Prevent a paused radar from catching up when inventory resumes. */
        app->radar_step_tick = now;
        return;
    }

    if(app->radar_step_tick == 0U) {
        app->radar_step_tick = now;
        return;
    }

    const uint32_t elapsed = now - app->radar_step_tick;
    if(elapsed < UHF_RADAR_STEP_MS) return;

    const uint32_t steps = elapsed / UHF_RADAR_STEP_MS;
    app->radar_sweep_phase = (uint8_t)((app->radar_sweep_phase + steps) % UHF_RADAR_PHASE_COUNT);
    if(app->page == UhfPageRadar && app->radar_trail_depth < 8U) {
        const uint32_t depth = app->radar_trail_depth + steps;
        app->radar_trail_depth = (uint8_t)(depth > 8U ? 8U : depth);
    }
    app->radar_step_tick += steps * UHF_RADAR_STEP_MS;
}

static size_t uhf_collect_tag_previews(
    UhfApp* app,
    size_t start,
    UhfTagPreview* out,
    size_t max_items,
    size_t* total) {
    if(!app || !out || !max_items || !total) return 0;
    if(!uhf_data_lock(app, 20)) return 0;

    uint8_t indices[UHF_MAX_TAGS];
    const size_t used_total = uhf_sorted_tag_indices(app, indices);
    const uint32_t now = furi_get_tick();
    size_t copied = 0U;
    for(size_t index = start; index < used_total && copied < max_items; index++) {
        const UhfTagEntry* tag = &app->tags[indices[index]];
        strncpy(out[copied].epc, tag->epc, sizeof(out[copied].epc) - 1);
        out[copied].epc[sizeof(out[copied].epc) - 1] = '\0';
        out[copied].count = tag->read_count;
        out[copied].signal_bars =
            tag->last_seen && now - tag->last_seen <= UHF_SIGNAL_FRESH_MS ? tag->signal_bars : 0U;
        copied++;
    }

    *total = used_total;
    uhf_data_unlock(app);
    return copied;
}

static void uhf_draw_centered_text(Canvas* canvas, int y, const char* text) {
    if(!canvas || !text) return;

    const int width = canvas_string_width(canvas, text);
    int x = (128 - width) / 2;
    if(x < 0) x = 0;
    canvas_draw_str(canvas, x, y, text);
}

static void uhf_draw_radar_ring(
    Canvas* canvas,
    int32_t center_x,
    int32_t center_y,
    const int8_t* ring_x,
    const int8_t* ring_y,
    int32_t scale) {
    for(uint8_t i = 0; i < 24U; i++) {
        const uint8_t next = (uint8_t)((i + 1U) % 24U);
        canvas_draw_line(
            canvas,
            center_x + ((int32_t)ring_x[i] * scale) / 27,
            center_y + ((int32_t)ring_y[i] * scale) / 27,
            center_x + ((int32_t)ring_x[next] * scale) / 27,
            center_y + ((int32_t)ring_y[next] * scale) / 27);
    }
}

static int32_t uhf_radar_sin(uint8_t phase) {
    static const uint8_t quarter_wave[25] = {
        0,  8,   17,  25,  33,  41,  49,  56,  63,  71,  77,  84,  90,
        95, 101, 106, 110, 114, 117, 120, 123, 125, 126, 127, 127,
    };

    phase %= UHF_RADAR_PHASE_COUNT;
    const uint8_t quadrant = phase / 24U;
    const uint8_t offset = phase % 24U;

    if(quadrant == 0U) return quarter_wave[offset];
    if(quadrant == 1U) return quarter_wave[24U - offset];
    if(quadrant == 2U) return -(int32_t)quarter_wave[offset];
    return -(int32_t)quarter_wave[24U - offset];
}

static void uhf_radar_vector(uint8_t phase, int32_t radius, int32_t* x, int32_t* y) {
    *x = (uhf_radar_sin(phase) * radius * 29) / (127 * 27);
    *y = -(uhf_radar_sin((uint8_t)(phase + 24U)) * radius) / 127;
}

static void uhf_draw_radar_page(Canvas* canvas, UhfApp* app) {
    static const int8_t sweep_x[24] = {
        0, 8,  15,  21,  25,  28,  29,  28,  25,  21,  15,  8,
        0, -8, -15, -21, -25, -28, -29, -28, -25, -21, -15, -8,
    };
    static const int8_t sweep_y[24] = {
        -27, -26, -23, -19, -14, -7, 0, 7,  14,  19,  23,  26,
        27,  26,  23,  19,  14,  7,  0, -7, -14, -19, -23, -26,
    };

    const int32_t center_x = 31;
    const int32_t center_y = 36;
    uint8_t target_x[UHF_MAX_TAGS];
    uint8_t target_y[UHF_MAX_TAGS];
    size_t target_count = 0;
    uint32_t rate = 0;
    size_t unique = 0;
    int16_t temperature = 0;
    uint8_t power_dbm = 0;
    bool temperature_valid = false;
    bool power_valid = false;
    uint8_t sweep_phase = 0;
    uint8_t trail_depth = 0;

    if(uhf_data_lock(app, 10)) {
        rate = app->tags_per_second;
        unique = app->tag_count;
        temperature = app->reader_temperature_c;
        power_dbm = app->reader_power_dbm;
        temperature_valid = app->temperature_valid;
        power_valid = app->power_valid;
        sweep_phase = app->radar_sweep_phase;
        trail_depth = app->radar_trail_depth;

        for(size_t i = 0; i < UHF_MAX_TAGS && target_count < UHF_MAX_TAGS; i++) {
            if(!app->tags[i].used) continue;

            /* Stable FNV-1a placement keeps each EPC at the same radar
               position while avoiding any artificial distance claim. */
            uint32_t hash = 2166136261U;
            for(const char* p = app->tags[i].epc; *p; p++) {
                hash ^= (uint8_t)*p;
                hash *= 16777619U;
            }

            /* Place targets across the upper semicircle (left horizon through
               top to right horizon), where they remain easiest to see. */
            const uint8_t upper_slot = (uint8_t)(hash % 13U);
            const uint8_t direction = (uint8_t)((18U + upper_slot) % 24U);
            const int32_t distance = 5 + (int32_t)((hash >> 8U) % 20U);
            const int32_t x = center_x + ((int32_t)sweep_x[direction] * distance) / 27;
            const int32_t y = center_y + ((int32_t)sweep_y[direction] * distance) / 27;
            target_x[target_count] = (uint8_t)x;
            target_y[target_count] = (uint8_t)y;
            target_count++;
        }
        uhf_data_unlock(app);
    }

    canvas_set_font(canvas, FontPrimary);
    const char* radar_title = "UHF Radar";
    const int32_t title_width = canvas_string_width(canvas, radar_title);
    canvas_draw_str(canvas, (65 - title_width) / 2, 8, radar_title);

    uhf_draw_radar_ring(canvas, center_x, center_y, sweep_x, sweep_y, 27);
    uhf_draw_radar_ring(canvas, center_x, center_y, sweep_x, sweep_y, 18);
    uhf_draw_radar_ring(canvas, center_x, center_y, sweep_x, sweep_y, 9);
    canvas_draw_dot(canvas, center_x, center_y);
    for(int32_t offset = -25; offset <= 25; offset += 5) {
        canvas_draw_dot(canvas, center_x + offset, center_y);
    }
    for(int32_t offset = -25; offset <= 25; offset += 5) {
        canvas_draw_dot(canvas, center_x, center_y + offset);
    }

    /* All trail segments keep their full length. Older segments use fewer
       pixels, creating a stable pseudo-gray fade on the 1-bit display. */
    for(uint8_t age = trail_depth; age > 0U; age--) {
        const uint8_t trail_phase =
            (uint8_t)((sweep_phase + UHF_RADAR_PHASE_COUNT - age) % UHF_RADAR_PHASE_COUNT);
        for(int32_t step = 4; step <= 27; step++) {
            if(((step + age) % (age + 1U)) != 0U) continue;
            int32_t trail_x = 0;
            int32_t trail_y = 0;
            uhf_radar_vector(trail_phase, step, &trail_x, &trail_y);
            canvas_draw_dot(canvas, center_x + trail_x, center_y + trail_y);
        }
    }

    int32_t sweep_dx = 0;
    int32_t sweep_dy = 0;
    uhf_radar_vector(sweep_phase, 27, &sweep_dx, &sweep_dy);
    canvas_draw_line(canvas, center_x, center_y, center_x + sweep_dx, center_y + sweep_dy);

    /* Draw a parallel one-pixel offset to make the leading sweep two pixels
       thick at every angle. */
    const int32_t abs_dx = sweep_dx < 0 ? -sweep_dx : sweep_dx;
    const int32_t abs_dy = sweep_dy < 0 ? -sweep_dy : sweep_dy;
    const int32_t offset_x = (abs_dy > abs_dx) ? ((sweep_dy > 0) ? -1 : 1) : 0;
    const int32_t offset_y = (abs_dy > abs_dx) ? 0 : ((sweep_dx >= 0) ? 1 : -1);
    canvas_draw_line(
        canvas,
        center_x + offset_x,
        center_y + offset_y,
        center_x + sweep_dx + offset_x,
        center_y + sweep_dy + offset_y);

    /* Draw targets last so they remain solid above the sweep and trail. */
    for(size_t i = 0; i < target_count; i++) {
        canvas_draw_box(canvas, (int32_t)target_x[i] - 1, (int32_t)target_y[i] - 1, 3, 3);
    }

    canvas_draw_line(canvas, 65, 0, 65, 63);

    canvas_set_font(canvas, FontSecondary);
    char value[24];

    canvas_draw_str(canvas, 70, 10, "RATE");
    if(rate > 9999U) {
        snprintf(value, sizeof(value), "9999+");
    } else {
        snprintf(value, sizeof(value), "%lu/s", (unsigned long)rate);
    }
    uhf_draw_right_text(canvas, 10, value);

    canvas_draw_str(canvas, 70, 26, "TAGS");
    snprintf(value, sizeof(value), "%lu", (unsigned long)unique);
    uhf_draw_right_text(canvas, 26, value);

    canvas_draw_str(canvas, 70, 42, "TEMP");
    if(temperature_valid) {
        snprintf(value, sizeof(value), "%d", (int)temperature);
    } else {
        snprintf(value, sizeof(value), "--");
    }
    uhf_draw_right_temperature(canvas, 42, value);

    canvas_draw_str(canvas, 70, 58, "PWR");
    if(power_valid) {
        snprintf(value, sizeof(value), "%udBm", power_dbm);
    } else {
        snprintf(value, sizeof(value), "--");
    }
    uhf_draw_right_text(canvas, 58, value);
}

static void uhf_input_callback(InputEvent* event, void* context) {
    if(!context || !event) return;
    UhfApp* app = context;
    UhfEvent app_event = {.input = *event};
    if(app->event_queue) {
        furi_message_queue_put(app->event_queue, &app_event, 0);
    }
}

static void
    uhf_draw_tag_bank_cycle_button(Canvas* canvas, UhfTagBank current_bank, bool include_reserved) {
    const UhfTagBank next_bank = include_reserved && current_bank == UhfTagBankUser ?
                                     UhfTagBankReserved :
                                     uhf_next_tag_bank(current_bank);
    const char* next_name = uhf_current_tag_bank_button_name(next_bank);
    const int32_t cycle_width = canvas_string_width(canvas, "Cycle");
    const int32_t label_width = canvas_string_width(canvas, next_name);
    const int32_t height = canvas_height(canvas);

    /* Keep the standard left button and its Cycle-sized background, then replace
       only the label inside it with the centered name of the next bank. */
    elements_button_left(canvas, "Cycle");
    canvas_set_color(canvas, ColorBlack);
    canvas_draw_box(canvas, 9, height - 11, cycle_width + 2U, 11);
    canvas_set_color(canvas, ColorWhite);
    canvas_draw_str(canvas, 10 + (cycle_width - label_width) / 2, height - 3, next_name);
    canvas_set_color(canvas, ColorBlack);
}

static bool uhf_select_scanned_tag(UhfApp* app, const char* preferred_epc) {
    UhfTagEntry tag;
    if(!app) return false;
    if(preferred_epc) {
        if(!uhf_data_lock(app, 20U)) return false;
        bool found = false;
        for(size_t i = 0U; i < UHF_MAX_TAGS; i++) {
            if(app->tags[i].used && strcmp(app->tags[i].epc, preferred_epc) == 0) {
                tag = app->tags[i];
                found = true;
                break;
            }
        }
        uhf_data_unlock(app);
        if(!found) return false;
    } else if(!uhf_copy_tag_at(app, 0U, &tag))
        return false;
    if(app->inventory_running) {
        uhf_stop_inventory(app);
        furi_delay_ms(UHF_STOP_SETTLE_MS);
        uhf_process_rx(app);
    }
    app->selected_tid_valid = false;
    app->selected_user_valid = false;
    strncpy(app->selected_epc, tag.epc, sizeof(app->selected_epc) - 1U);
    app->selected_epc[sizeof(app->selected_epc) - 1U] = '\0';
    strncpy(app->access_epc, tag.epc, sizeof(app->access_epc) - 1U);
    app->access_epc[sizeof(app->access_epc) - 1U] = '\0';
    return true;
}

static size_t uhf_ascii_confirmed_tags(UhfApp* app, char* single_epc, size_t epc_size) {
    if(!app || !single_epc || !epc_size || !uhf_data_lock(app, 20U)) return 0U;
    single_epc[0] = '\0';
    const uint32_t now = furi_get_tick();
    size_t count = 0U;
    for(size_t i = 0U; i < UHF_MAX_TAGS; i++) {
        const UhfTagEntry* tag = &app->tags[i];
        if(!tag->used || tag->read_count < 2U || now - tag->last_seen > 1200U) continue;
        if(count++ == 0U) {
            strncpy(single_epc, tag->epc, epc_size - 1U);
            single_epc[epc_size - 1U] = '\0';
        }
    }
    uhf_data_unlock(app);
    return count;
}

static void uhf_make_fuzz_epc(UhfApp* app) {
    if(!app || !app->fuzz_base_epc[0]) return;
    strncpy(app->selected_epc, app->fuzz_base_epc, sizeof(app->selected_epc) - 1U);
    app->selected_epc[sizeof(app->selected_epc) - 1U] = '\0';
    const size_t len = strlen(app->selected_epc);
    const size_t digits = len < 8U ? len : 8U;
    uint32_t tail = 0U;
    for(size_t i = len - digits; i < len; i++) {
        const char c = app->selected_epc[i];
        tail = (tail << 4U) | (uint32_t)(c <= '9' ? c - '0' : 10 + c - 'A');
    }
    tail += app->fuzz_sequence;
    static const char hex[] = "0123456789ABCDEF";
    for(size_t i = 0; i < digits; i++) {
        app->selected_epc[len - 1U - i] = hex[(tail >> (i * 4U)) & 0x0FU];
    }
}

static uint8_t uhf_startup_feature(UhfStartupApp startup_app) {
    switch(startup_app) {
    case UhfStartupRadar:
        return 0U;
    case UhfStartupInventory:
        return 1U;
    case UhfStartupEpcFuzzing:
        return 2U;
    case UhfStartupTidDecoder:
        return 4U;
    default:
        return 0U;
    }
}

static void uhf_enter_feature(UhfApp* app, uint8_t feature) {
    if(!app) return;
    app->memory_readonly = false;
    switch(feature) {
    case 0:
        app->page = UhfPageRadar;
        app->radar_trail_depth = 0U;
        app->radar_step_tick = furi_get_tick();
        uhf_start_inventory(app);
        break;
    case 1:
        app->ascii_filter_active = false;
        app->page = UhfPageList;
        app->list_selection_manual = false;
        uhf_start_inventory(app);
        break;
    case 2:
        uhf_clear_tags(app);
        app->access_epc[0] = '\0';
        app->fuzz_base_epc[0] = '\0';
        app->fuzz_sequence = 0U;
        app->tag_access_unfiltered = false;
        app->page = UhfPageEpcFuzzing;
        uhf_start_inventory(app);
        uhf_set_status(app, "Read one source tag");
        break;
    case 3:
        uhf_clear_tags(app);
        app->ascii_tag_captured = false;
        app->ascii_single_since = 0U;
        app->ascii_candidate_epc[0] = '\0';
        app->ascii_source_epc[0] = '\0';
        app->ascii_text[0] = '\0';
        app->tag_access_unfiltered = false;
        app->page = UhfPageAscii;
        uhf_start_inventory(app);
        uhf_set_status(app, "Present one tag");
        break;
    case 8: {
        char pending[sizeof(app->ascii_filter)] = "";
        if(!uhf_prompt_epc_filter(app, pending, sizeof(pending))) break;
        if(app->inventory_running) uhf_stop_inventory(app);
        bool reader_buzzer_disabled = true;
        if(app->reader_buzzer_enabled) {
            app->reader_buzzer_enabled = false;
            reader_buzzer_disabled = uhf_set_reader_buzzer(app);
            app->reader_buzzer_enabled = true;
            app->ascii_filter_buzzer_suspended = true;
        }
        uhf_clear_tags(app);
        strcpy(app->ascii_filter, pending);
        for(char* p = app->ascii_filter; *p; p++)
            *p = uhf_ascii_lower(*p);
        app->ascii_filter_active = true;
        app->ascii_filter_fullscreen = false;
        app->page = UhfPageList;
        uhf_start_inventory(app);
        if(!reader_buzzer_disabled) uhf_set_status(app, "Reader buzzer may still sound");
        break;
    }
    case 4:
        uhf_clear_tags(app);
        app->selected_tid_valid = false;
        app->tid_decode_attempted = false;
        app->tag_data_scroll_line = 0U;
        app->page = UhfPageTidDecoder;
        uhf_start_inventory(app);
        uhf_set_status(app, "Present exactly one tag");
        break;
    case 5:
        uhf_clear_tags(app);
        app->security_mode = true;
        app->security_single_since = 0U;
        app->tag_access_unfiltered = false;
        app->page = UhfPageTagSecurity;
        uhf_start_inventory(app);
        uhf_set_status(app, "Present exactly one tag");
        break;
    case 6:
        app->page = UhfPageKeyVault;
        app->key_vault_selected_slot = app->active_key_slot;
        uhf_set_status(app, "Select key slot");
        break;
    case 7:
        app->page = UhfPageSettings;
        app->settings_reader_mode = false;
        app->settings_selected = 0U;
        break;
    default:
        uhf_enter_about_page(app);
        break;
    }
}

static void uhf_enter_main_feature(UhfApp* app) {
    if(!app) return;
    app->home_tool_selected = 0U;
    app->feature_return_page = UhfPageMainMenu;
    switch(app->main_menu_selected) {
    case 0:
        uhf_enter_feature(app, 0U);
        break;
    case 1:
        uhf_enter_feature(app, 1U);
        break;
    case 2:
        app->page = UhfPageHomeTagTools;
        break;
    case 3:
        app->page = UhfPageHomeEpcTools;
        break;
    case 4:
        app->saved_list_return = UhfPageMainMenu;
        app->saved_selected = 0U;
        uhf_refresh_saved_tags(app);
        app->page = UhfPageSavedList;
        break;
    case 5:
        app->page = UhfPageHomeSettings;
        break;
    }
}

static void uhf_service_feature_page(UhfApp* app) {
    if(!app || !app->inventory_running) return;

    if((app->page == UhfPageTidDecoder && !app->selected_tid_valid) ||
       app->page == UhfPageTagSecurity ||
       (app->page == UhfPageAscii && !app->ascii_tag_captured)) {
        /* Inventory keeps a history of EPCs. Expire tags no longer in the RF
           field so removing all but one tag can continue without re-entering. */
        uhf_prune_stale_tags(app, 800U);
    }
    const size_t feature_tag_count = uhf_count_tags(app);
    if(app->page == UhfPageAscii && !app->ascii_tag_captured) {
        char candidate[UHF_EPC_HEX_MAX + 1U];
        const size_t confirmed = uhf_ascii_confirmed_tags(app, candidate, sizeof(candidate));
        if(confirmed != 1U) {
            app->ascii_single_since = 0U;
            app->ascii_candidate_epc[0] = '\0';
            return;
        }
        const uint32_t now = furi_get_tick();
        if(strcmp(app->ascii_candidate_epc, candidate) != 0) {
            strncpy(app->ascii_candidate_epc, candidate, sizeof(app->ascii_candidate_epc) - 1U);
            app->ascii_candidate_epc[sizeof(app->ascii_candidate_epc) - 1U] = '\0';
            app->ascii_single_since = now;
            return;
        }
        if((now - app->ascii_single_since) < UHF_SINGLE_TAG_STABLE_MS) return;
    } else if(app->page == UhfPageTagSecurity) {
        if(feature_tag_count != 1U) {
            app->security_single_since = 0U;
            return;
        }
        const uint32_t now = furi_get_tick();
        if(app->security_single_since == 0U) {
            app->security_single_since = now;
            return;
        }
        if((now - app->security_single_since) < UHF_SINGLE_TAG_STABLE_MS) return;
    } else if(feature_tag_count != 1U) {
        return;
    }

    if(app->page == UhfPageAscii && !app->ascii_tag_captured) {
        if(uhf_select_scanned_tag(app, app->ascii_candidate_epc)) {
            strncpy(app->ascii_source_epc, app->access_epc, sizeof(app->ascii_source_epc) - 1U);
            app->ascii_source_epc[sizeof(app->ascii_source_epc) - 1U] = '\0';
            if(!uhf_epc_hex_to_ascii(
                   app->ascii_source_epc, app->ascii_text, sizeof(app->ascii_text))) {
                app->ascii_text[0] = '\0';
            }
            app->ascii_tag_captured = true;
            uhf_set_status(
                app,
                app->ascii_text[0] ? "Tag captured; edit or write" : "Tag captured; press Edit");
        }
    } else if(app->page == UhfPageTagSecurity) {
        if(uhf_select_scanned_tag(app, NULL)) {
            app->tag_bank = UhfTagBankEpc;
            app->tag_action_selected = 0U;
            app->tag_action_top = 0U;
            app->page = UhfPageTagActions;
            uhf_set_status(app, "Choose bank; press OK");
        }
    } else if(app->page == UhfPageTidDecoder && !app->tid_decode_attempted) {
        app->tid_decode_attempted = true;
        if(uhf_select_scanned_tag(app, NULL)) {
            app->tag_access_unfiltered = false;
            app->epc_filter_active = false;
            app->tag_data_scroll_line = 0U;
            (void)uhf_read_selected_tid(app);
        }
    } else if(app->page == UhfPageEpcFuzzing && !app->fuzz_base_epc[0]) {
        if(uhf_select_scanned_tag(app, NULL)) {
            strncpy(app->fuzz_base_epc, app->access_epc, sizeof(app->fuzz_base_epc) - 1U);
            app->fuzz_base_epc[sizeof(app->fuzz_base_epc) - 1U] = '\0';
            app->fuzz_sequence = 0U;
            uhf_make_fuzz_epc(app);
            uhf_set_status(app, "Source EPC captured");
        }
    }
}

/* Three-pixel glyphs with one-pixel spacing fit full names in a 62px tile. */
static void uhf_draw_menu_label(Canvas* canvas, int x, int y, const char* text) {
    static const uint16_t glyphs[] = {
        0x5BEA, 0x3AEB, 0x624E, 0x3B6B, 0x72CF, 0x12CF, 0x6B4E, 0x5BED, 0x7497,
        0x2B24, 0x5AED, 0x7249, 0x5BFD, 0x5B6B, 0x2B6A, 0x12EB, 0x4D6A, 0x5AEB,
        0x388E, 0x2497, 0x7B6D, 0x2B6D, 0x5FED, 0x5AAD, 0x24AD, 0x72A7,
    };
    for(; *text; text++, x += 4) {
        const char c = (char)toupper((unsigned char)*text);
        static const uint16_t digits[] = {
            0x7b6f, 0x749a, 0x72a3, 0x38a3, 0x49ed, 0x38cf, 0x7bce, 0x24a7, 0x7bef, 0x39ef};
        uint16_t glyph;
        if(c >= 'A' && c <= 'Z')
            glyph = glyphs[c - 'A'];
        else if(c >= '0' && c <= '9')
            glyph = digits[c - '0'];
        else
            continue;
        for(unsigned row = 0; row < 5; row++) {
            for(unsigned col = 0; col < 3; col++) {
                if(glyph & (1U << (row * 3U + col))) canvas_draw_dot(canvas, x + col, y + row);
            }
        }
    }
}

static void uhf_draw_main_menu(Canvas* canvas, UhfApp* app) {
    canvas_set_font(canvas, FontPrimary);
    uhf_draw_centered_text(canvas, 10, "UHF Expansion");

    canvas_set_font(canvas, FontKeyboard);
    const size_t first = (size_t)app->main_menu_top_row * 2U;
    const size_t end = first + 6U < COUNT_OF(uhf_main_menu_items) ? first + 6U :
                                                                    COUNT_OF(uhf_main_menu_items);
    for(size_t i = first; i < end; i++) {
        const size_t visible = i - first;
        const int x = (int)(visible % 2U) * 64;
        const int y = 13 + (int)(visible / 2U) * 17;
        const bool selected = i == app->main_menu_selected;
        if(selected) {
            canvas_draw_rbox(canvas, x + 1, y + 1, 62, 16, 3);
            canvas_set_color(canvas, ColorWhite);
        } else {
            canvas_draw_rframe(canvas, x + 1, y + 1, 62, 16, 3);
        }

        /* Compact, code-drawn icons keep the grid legible without extra assets. */
        const int ix = x + 4;
        const int iy = y + 5;
        static const uint8_t icons[6][7] = {
            {0x1c, 0x22, 0x51, 0x59, 0x45, 0x22, 0x1c}, /* Radar */
            {0x7d, 0x0, 0x0, 0x7d, 0x0, 0x0, 0x7d}, /* Inventory */
            {0x1c, 0x22, 0x22, 0x7f, 0x49, 0x49, 0x7f}, /* Tag Tools */
            {0x1c, 0x22, 0x22, 0x3e, 0x22, 0x22, 0x22}, /* EPC Tools */
            {0x7f, 0x41, 0x5d, 0x41, 0x5d, 0x41, 0x7f}, /* Saved Tags */
            {0x4, 0x7f, 0x4, 0x0, 0x10, 0x7f, 0x10}, /* Settings */
        };
        for(unsigned row = 0; row < 7U; row++) {
            for(unsigned col = 0; col < 7U; col++) {
                if(icons[i][row] & (1U << col)) {
                    canvas_draw_dot(canvas, ix + 1 + col, iy + 1 + row);
                }
            }
        }
        uhf_draw_menu_label(canvas, x + 16, y + 7, uhf_main_menu_items[i]);
        if(selected) canvas_set_color(canvas, ColorBlack);
    }
}

static const char* uhf_tid_vendor(uint16_t mdid) {
    switch(mdid) {
    case 0x001:
        return "Impinj";
    case 0x003:
        return "Alien";
    case 0x006:
        return "NXP";
    case 0x007:
        return "STMicro";
    case 0x00B:
        return "EM Micro";
    case 0x01B:
        return "Invengo";
    case 0x01D:
        return "Kiloway";
    default:
        return "Unknown";
    }
}

static const char* uhf_tid_model(uint16_t mdid, uint16_t tmn) {
    if(mdid == 0x001U) {
        switch(tmn) {
        case 0x100:
            return "Monza 4D";
        case 0x105:
            return "Monza 4QT";
        case 0x10C:
            return "Monza 4E";
        case 0x114:
            return "Monza 4i";
        case 0x160:
            return "Monza R6";
        case 0x170:
            return "Monza R6-P";
        case 0x171:
            return "Monza R6-A/B";
        default:
            break;
        }
    } else if(mdid == 0x003U) {
        if(tmn == 0x412U) return "Higgs-3";
        if(tmn == 0x414U) return "Higgs-4";
    } else if(mdid == 0x006U) {
        switch(tmn) {
        case 0x003:
            return "UCODE G2XM";
        case 0x004:
            return "UCODE G2XL";
        case 0x806:
        case 0x906:
        case 0xB06:
            return "UCODE G2iL";
        case 0x807:
        case 0x907:
        case 0xB07:
            return "UCODE G2iL+";
        case 0x80A:
            return "UCODE G2iM";
        case 0x80B:
            return "UCODE G2iM+";
        case 0x890:
            return "UCODE 7";
        case 0x915:
        case 0x995:
            return "UCODE 9";
        case 0xA16:
        case 0xA96:
            return "UCODE 9xe";
        default:
            break;
        }
    }
    return "Unknown";
}

static void uhf_draw_tid_decoder(Canvas* canvas, UhfApp* app) {
    uhf_draw_centered_text(canvas, 9, "TID Decoder");
    canvas_set_font(canvas, FontSecondary);
    if(!app->selected_tid_valid) {
        const size_t count = uhf_count_tags(app);
        uhf_draw_centered_text(
            canvas,
            29,
            app->tid_decode_attempted ? "TID read failed" :
                                        (count > 1U ? "Too many tags" : "Reading tag..."));
        uhf_draw_centered_text(
            canvas, 42, app->tid_decode_attempted ? "OK to retry" : "Present one tag");
        return;
    }

    const char* tid = app->selected_tid;
    const size_t length = strlen(tid);
    uint8_t bytes[4] = {0};
    size_t byte_count = 0U;
    char prefix[9] = {0};
    if(length >= 8U) memcpy(prefix, tid, 8U);
    const bool decoded = length >= 8U && strncmp(tid, "E2", 2U) == 0 &&
                         uhf_hex_to_bytes(prefix, bytes, sizeof(bytes), &byte_count) &&
                         byte_count == 4U;

    /* Chip silhouette and two compact identity fields share a single card. */
    canvas_draw_rframe(canvas, 0, 11, 128, 25, 3);
    canvas_draw_rbox(canvas, 7, 16, 17, 15, 2);
    for(int pin = 0; pin < 3; pin++) {
        canvas_draw_line(canvas, 4, 18 + pin * 5, 6, 18 + pin * 5);
        canvas_draw_line(canvas, 25, 18 + pin * 5, 27, 18 + pin * 5);
    }
    canvas_set_color(canvas, ColorWhite);
    canvas_draw_frame(canvas, 11, 19, 9, 9);
    canvas_set_color(canvas, ColorBlack);
    canvas_draw_line(canvas, 33, 14, 33, 33);
    char field[28];
    uint16_t mdid = 0U;
    uint16_t tmn = 0U;
    if(decoded) {
        mdid = (uint16_t)(((bytes[1] & 0x1FU) << 4U) | (bytes[2] >> 4U));
        tmn = (uint16_t)(((bytes[2] & 0x0FU) << 8U) | bytes[3]);
        snprintf(field, sizeof(field), "%s  %03X", uhf_tid_vendor(mdid), mdid);
    } else {
        snprintf(field, sizeof(field), "MDID  Unknown");
    }
    canvas_draw_str(canvas, 39, 21, field);
    if(decoded) {
        snprintf(field, sizeof(field), "%s  %03X", uhf_tid_model(mdid, tmn), tmn);
    } else {
        snprintf(field, sizeof(field), "Model Unknown");
    }
    canvas_draw_str(canvas, 39, 32, field);

    const size_t bytes_per_row = 8U;
    const size_t bytes_per_page = bytes_per_row * 2U;
    const size_t byte_length = length / 2U;
    const size_t pages = (byte_length + bytes_per_page - 1U) / bytes_per_page;
    const size_t page = pages && app->tag_data_scroll_line >= pages ? pages - 1U :
                                                                      app->tag_data_scroll_line;
    canvas_draw_rframe(canvas, 0, 40, 128, 24, 3);
    canvas_set_color(canvas, ColorWhite);
    canvas_draw_box(canvas, 6, 37, 19, 8);
    canvas_set_color(canvas, ColorBlack);
    canvas_draw_str(canvas, 9, 44, "TID");
    if(pages > 1U) {
        snprintf(
            field, sizeof(field), "%lu/%lu", (unsigned long)(page + 1U), (unsigned long)pages);
        uhf_draw_right_text(canvas, 44, field);
    }
    canvas_set_font(canvas, FontKeyboard);
    for(size_t row = 0; row < 2U; row++) {
        const size_t byte_offset = page * bytes_per_page + row * bytes_per_row;
        if(byte_offset >= byte_length) break;
        char part[24];
        uhf_format_hex_byte_groups(tid, length, byte_offset, bytes_per_row, part, sizeof(part));
        canvas_draw_str(canvas, 3, 53 + (int)row * 9, part);
    }
}

static void uhf_draw_epc_fuzzing(Canvas* canvas, UhfApp* app) {
    uhf_draw_centered_text(canvas, 9, "EPC Fuzzing");
    canvas_set_font(canvas, FontSecondary);
    if(!app->fuzz_base_epc[0]) {
        const size_t count = uhf_count_tags(app);
        uhf_draw_centered_text(
            canvas,
            30,
            count > 1U ? "Too many tags" :
                         (count == 1U ? "Source found - press OK" : "Present source tag..."));
    } else {
        char line[24];
        snprintf(line, sizeof(line), "#: %lu", (unsigned long)app->fuzz_sequence);
        canvas_draw_str(canvas, 2, 20, line);
        const size_t length = strlen(app->selected_epc);
        const size_t byte_length = length / 2U;
        if(byte_length <= 24U) {
            canvas_set_font(canvas, FontKeyboard);
            for(size_t row = 0U; row < 3U; row++) {
                const size_t byte_offset = row * 8U;
                if(byte_offset >= byte_length) break;
                char part[24];
                uhf_format_hex_byte_groups(
                    app->selected_epc, length, byte_offset, 8U, part, sizeof(part));
                canvas_draw_str(canvas, 2, 30 + (int)row * 9, part);
            }
        } else {
            /* The compact glyphs are also fixed-width and keep a full 48-byte
               EPC visible while preserving byte grouping. */
            for(size_t row = 0U; row < 5U; row++) {
                const size_t byte_offset = row * 10U;
                if(byte_offset >= byte_length) break;
                char part[30];
                uhf_format_hex_byte_groups(
                    app->selected_epc, length, byte_offset, 10U, part, sizeof(part));
                uhf_draw_menu_label(canvas, 2, 23 + (int)row * 7, part);
            }
        }
        canvas_set_font(canvas, FontSecondary);
    }
    if(app->fuzz_base_epc[0]) {
        uhf_draw_fixed_side_button(canvas, "Clear", false);
        uhf_draw_fixed_center_button(canvas, "Edit");
        uhf_draw_fixed_side_button(canvas, "Write", true);
    } else {
        uhf_draw_fixed_center_button(canvas, "Read");
    }
}

static void uhf_draw_ascii(Canvas* canvas, UhfApp* app) {
    uhf_draw_centered_text(canvas, 9, "EPC ASCII");
    canvas_set_font(canvas, FontSecondary);

    if(!app->ascii_tag_captured) {
        char candidate[UHF_EPC_HEX_MAX + 1U];
        const size_t count = uhf_ascii_confirmed_tags(app, candidate, sizeof(candidate));
        const size_t seen = uhf_count_tags(app);
        uhf_draw_centered_text(
            canvas,
            29,
            count > 1U ? "Too many tags" :
                         (count == 1U || seen ? "Tag found..." : "Present one tag"));
        uhf_draw_centered_text(canvas, 42, "Then edit ASCII");
        uhf_draw_fixed_center_button(canvas, app->inventory_running ? "Stop" : "Scan");
        return;
    }

    canvas_draw_rframe(canvas, 0, 14, 128, 35, 3);
    canvas_set_font(canvas, FontKeyboard);
    const size_t epc_length = strlen(app->ascii_source_epc);
    const int glyph_width = canvas_string_width(canvas, "0");
    const size_t chars_per_line = glyph_width > 0 ? ((size_t)(120 / glyph_width) & ~1U) : 0U;
    if(chars_per_line >= 2U) {
        char line[UHF_EPC_HEX_MAX + 1U];
        const size_t first_length = MIN(epc_length, chars_per_line);
        memcpy(line, app->ascii_source_epc, first_length);
        line[first_length] = '\0';
        canvas_draw_str(canvas, 4, 23, line);
        if(epc_length > first_length) {
            const size_t remaining = epc_length - first_length;
            const size_t second_length = MIN(remaining, chars_per_line);
            memcpy(line, app->ascii_source_epc + first_length, second_length);
            line[second_length] = '\0';
            canvas_draw_str(canvas, 4, 34, line);
        }
    }

    canvas_set_font(canvas, FontSecondary);
    canvas_draw_str(canvas, 4, 47, app->ascii_text[0] ? app->ascii_text : "<empty>");

    uhf_draw_fixed_side_button(canvas, "Clear", false);
    uhf_draw_fixed_center_button(canvas, "Edit");
    uhf_draw_fixed_side_button(canvas, "Write", true);
}

static void uhf_draw_settings(Canvas* canvas, UhfApp* app) {
    uhf_draw_centered_text(
        canvas, 9, app->settings_reader_mode ? "Reader Settings" : "App Settings");
    canvas_set_font(canvas, FontSecondary);
    static const char* const app_labels[] = {
        "Sound", "EPC Display", "Startup App", "Action Confirm"};
    static const char* const reader_labels[] = {"Indicator", "RF Power", "Reset"};
    const char* const* labels = app->settings_reader_mode ? reader_labels : app_labels;
    char values[4][20];
    if(app->settings_reader_mode) {
        snprintf(
            values[0], sizeof(values[0]), "< %s >", app->reader_buzzer_enabled ? "ON" : "OFF");
        snprintf(values[1], sizeof(values[1]), "< %u dBm >", app->reader_power_dbm);
        snprintf(values[2], sizeof(values[2]), "Press OK");
    } else {
        snprintf(values[0], sizeof(values[0]), "< %s >", app->tag_beep_enabled ? "ON" : "OFF");
        snprintf(
            values[1],
            sizeof(values[1]),
            "< %s >",
            app->epc_display == UhfEpcDisplayAscii ? "ASCII" : "HEX");
        snprintf(values[2], sizeof(values[2]), "< %s >", uhf_startup_names[app->startup_app]);
        snprintf(values[3], sizeof(values[3]), "< %s >", app->action_confirm ? "Yes" : "No");
    }
    const size_t total_rows = app->settings_reader_mode ? COUNT_OF(reader_labels) :
                                                          COUNT_OF(app_labels);
    const size_t visible_rows = 3U;
    const size_t top =
        app->settings_selected >= visible_rows ? app->settings_selected - visible_rows + 1U : 0U;
    for(size_t row = 0U; row < visible_rows; row++) {
        const size_t item = top + row;
        const int y = 12 + (int)row * 13;
        if(item == app->settings_selected) {
            canvas_draw_box(canvas, 0, y, 123, 13);
            canvas_set_color(canvas, ColorWhite);
        }
        canvas_draw_str(canvas, 3, y + 9, labels[item]);
        canvas_draw_str(
            canvas, 120 - canvas_string_width(canvas, values[item]), y + 9, values[item]);
        if(item == app->settings_selected) canvas_set_color(canvas, ColorBlack);
    }
    elements_scrollbar_pos(canvas, 125, 12, 39, app->settings_selected, total_rows);
    uhf_draw_fixed_center_button(
        canvas, app->settings_reader_mode && app->settings_selected == 2U ? "Reset" : "Save");
}

