static void uhf_draw_key_vault(Canvas* canvas, UhfApp* app) {
    uhf_draw_centered_text(canvas, 9, "Access Keys");
    canvas_set_font(canvas, FontSecondary);
    for(uint8_t slot = 0U; slot < UHF_KEY_SLOT_COUNT; slot++) {
        const int y = 21 + (int)slot * 10;
        const uint8_t* key = app->access_keys[slot];
        const bool set = key[0] || key[1] || key[2] || key[3];
        if(slot == app->key_vault_selected_slot) {
            canvas_draw_box(canvas, 7, y - 8, 114, 10);
            canvas_set_color(canvas, ColorWhite);
        }
        canvas_draw_circle(canvas, 13, y - 3, 3);
        if(slot == app->active_key_slot) canvas_draw_disc(canvas, 13, y - 3, 1);
        char line[24];
        snprintf(line, sizeof(line), "Slot %u  %s", slot + 1U, set ? "********" : "00000000");
        canvas_draw_str(canvas, 21, y, line);
        if(slot == app->key_vault_selected_slot) canvas_set_color(canvas, ColorBlack);
    }
    uhf_draw_fixed_center_button(canvas, "Use");
    uhf_draw_fixed_side_button(canvas, "Edit", true);
}

static void uhf_draw_save_popup(Canvas* canvas, const UhfApp* app) {
    const int left = 8;
    const int width = 112;
    const int text_left = left + 7;
    const int text_right = left + width - 7;
    const int max_width = text_right - text_left;

    canvas_set_font(canvas, FontSecondary);

    char detail[64];
    if(app->write_popup_active) {
        snprintf(detail, sizeof(detail), "%s", app->write_popup_text);
    } else if(app->save_popup_csv) {
        snprintf(detail, sizeof(detail), "%s saved", app->csv_filename);
    } else {
        strncpy(detail, app->status, sizeof(detail) - 1U);
        detail[sizeof(detail) - 1U] = '\0';
    }
    char line[2][32] = {{0}};
    size_t source_pos = 0U;
    size_t line_count = 0U;
    for(size_t row = 0U; row < 2U && detail[source_pos]; row++) {
        size_t written = 0U;
        while(detail[source_pos] && written < sizeof(line[row]) - 4U) {
            line[row][written] = detail[source_pos];
            line[row][written + 1U] = '\0';
            if(canvas_string_width(canvas, line[row]) > max_width) {
                line[row][written] = '\0';
                break;
            }
            source_pos++;
            written++;
        }
        if(row == 0U && detail[source_pos]) {
            char* last_space = strrchr(line[row], ' ');
            if(last_space && last_space != line[row]) {
                const size_t word_start = (size_t)(last_space - line[row]) + 1U;
                if(line[row][word_start] != '\0') {
                    source_pos -= strlen(line[row]) - word_start;
                    *last_space = '\0';
                }
            }
        }
        if(!detail[source_pos]) {
            line_count = row + 1U;
            break;
        }
        if(row == 1U) {
            size_t length = strlen(line[row]);
            while(length > 0U &&
                  canvas_string_width(canvas, line[row]) + canvas_string_width(canvas, "...") >
                      max_width) {
                line[row][--length] = '\0';
            }
            line[row][length++] = '.';
            line[row][length++] = '.';
            line[row][length++] = '.';
            line[row][length] = '\0';
        }
        line_count = row + 1U;
    }

    const int height = line_count <= 1U ? 22 : 31;
    const int top = (64 - height) / 2;
    canvas_set_color(canvas, ColorWhite);
    canvas_draw_rbox(canvas, left, top, width, height, 4);
    canvas_set_color(canvas, ColorBlack);
    canvas_draw_rframe(canvas, left, top, width, height, 4);
    const int first_y = line_count == 1U ? top + 14 : top + 13;
    for(size_t row = 0U; row < line_count; row++) {
        const int text_width = canvas_string_width(canvas, line[row]);
        const int text_x = left + (width - text_width) / 2;
        canvas_draw_str(canvas, text_x, first_y + (int)row * 9, line[row]);
    }
}

static const char* const uhf_memory_banks[] = {"RESERVED", "EPC", "TID", "USER"};

static void uhf_draw_action_menu(
    Canvas* canvas,
    const char* title,
    const char* const* items,
    size_t count,
    uint8_t selected) {
    canvas_set_font(canvas, FontPrimary);
    uhf_draw_centered_text(canvas, 9, title);
    canvas_set_font(canvas, FontSecondary);
    /* Scroll longer menus within four rows above the bottom button strip. */
    const size_t visible = MIN(count, 4U);
    const size_t top = selected >= visible ? selected - visible + 1U : 0U;
    const int first_y = visible == 4U ? 19 : 24;
    const int row_step = visible == 4U ? 10 : 11;
    for(size_t row = 0U; row < visible; row++) {
        const size_t i = top + row;
        const int y = first_y + (int)row * row_step;
        if(i == selected) {
            canvas_draw_rbox(canvas, 7, y - 8, 114, 10, 2);
            canvas_set_color(canvas, ColorWhite);
        }
        canvas_draw_str(canvas, 13, y, items[i]);
        if(i == selected) canvas_set_color(canvas, ColorBlack);
    }
    if(count > visible) elements_scrollbar_pos(canvas, 125, 13, 38, selected, count);
    elements_button_center(canvas, "Select");
}

static void uhf_draw_home_tools(Canvas* canvas, UhfApp* app) {
    if(app->page == UhfPageHomeTagTools)
        uhf_draw_action_menu(canvas, "Tag Tools", uhf_home_tag_tools, 3U, app->home_tool_selected);
    else if(app->page == UhfPageHomeEpcTools)
        uhf_draw_action_menu(canvas, "EPC Tools", uhf_home_epc_tools, 3U, app->home_tool_selected);
    else if(app->page == UhfPageHomeSettings)
        uhf_draw_action_menu(canvas, "Settings", uhf_home_settings, 3U, app->home_tool_selected);
}

static void uhf_draw_saved_tags(Canvas* canvas, UhfApp* app) {
    canvas_set_font(canvas, FontPrimary);
    if(app->page == UhfPageSavedList) {
        canvas_draw_str(canvas, 0, 9, "Saved Tags");
        if(app->saved_count)
            uhf_draw_right_fraction(canvas, 9, app->saved_selected + 1U, app->saved_count);
        canvas_set_font(canvas, FontSecondary);
        if(!app->saved_count) {
            uhf_draw_centered_text(
                canvas, 32, app->saved_list_ok ? "No saved tags" : "Storage read failed");
        } else {
            const size_t top = app->saved_selected >= 4U ? app->saved_selected - 3U : 0U;
            for(size_t row = 0U; row < 4U && top + row < app->saved_count; row++) {
                const int y = 19 + (int)row * 10;
                if(top + row == app->saved_selected) {
                    canvas_draw_rbox(canvas, 7, y - 8, 114, 10, 2);
                    canvas_set_color(canvas, ColorWhite);
                }
                const char* label =
                    top == app->saved_visible_top ? app->saved_visible_labels[row] : "Tag";
                canvas_draw_str(canvas, 13, y, label);
                canvas_set_color(canvas, ColorBlack);
            }
            elements_scrollbar_pos(canvas, 125, 13, 38, app->saved_selected, app->saved_count);
        }
        elements_button_center(canvas, app->saved_count ? "Open" : "Refresh");
        return;
    }
    char title[32];
    if(app->saved_tag.name[0])
        snprintf(title, sizeof(title), "%s", app->saved_tag.name);
    else
        snprintf(title, sizeof(title), "Tag %03u", app->saved_id);
    if(app->page == UhfPageSavedMenu) {
        const char* items[] = {"View", "Delete"};
        uhf_draw_action_menu(canvas, title, items, COUNT_OF(items), app->saved_action);
    } else if(app->page == UhfPageSavedDelete) {
        uhf_draw_centered_text(canvas, 9, "Confirm Delete");
        canvas_set_font(canvas, FontSecondary);
        char prompt[32];
        snprintf(prompt, sizeof(prompt), "Delete Tag %03u?", app->saved_id);
        uhf_draw_centered_text(canvas, 30, prompt);
        uhf_draw_centered_text(canvas, 44, "BACK: Cancel");
        elements_button_center(canvas, "OK");
    } else if(app->page == UhfPageSavedResult) {
        uhf_draw_centered_text(canvas, 9, "Saved Tags");
        canvas_set_font(canvas, FontSecondary);
        char compact[40];
        uhf_format_list_epc_compact(canvas, app->saved_result, 126, compact, sizeof(compact));
        uhf_draw_centered_text(canvas, 32, compact);
        elements_button_center(canvas, "Back");
    } else {
        uhf_draw_centered_text(canvas, 9, title);
        canvas_set_font(canvas, FontSecondary);
        static const char* const banks[] = {"EPC", "TID", "User Data", "Info"};
        const char* bank = banks[app->saved_bank];
        canvas_draw_rframe(canvas, 0, 14, 128, 37, 3);
        canvas_set_color(canvas, ColorWhite);
        canvas_draw_box(canvas, 5, 11, canvas_string_width(canvas, bank) + 6U, 8);
        canvas_set_color(canvas, ColorBlack);
        canvas_draw_str(canvas, 8, 18, bank);
        if(app->saved_bank == 3U) {
            char metadata[32];
            snprintf(
                metadata,
                sizeof(metadata),
                "PC: %02X %02X",
                app->saved_tag.pc >> 8U,
                app->saved_tag.pc & 0xFFU);
            canvas_draw_str(canvas, 6, 28, metadata);
            snprintf(metadata, sizeof(metadata), "RSSI: %lu", (unsigned long)app->saved_tag.rssi);
            canvas_draw_str(canvas, 6, 37, metadata);
            canvas_draw_str(
                canvas,
                6,
                46,
                app->saved_tag.timestamp[0] ? app->saved_tag.timestamp : "No timestamp");
        } else {
            const char* value = app->saved_bank == 0U ? app->saved_tag.epc :
                                app->saved_bank == 1U ? app->saved_tag.tid :
                                                        app->saved_tag.user;
            const size_t length = strlen(value);
            if(!length)
                uhf_draw_centered_text(canvas, 37, "Not recorded");
            else {
                char size[12];
                snprintf(size, sizeof(size), "%luB", (unsigned long)(length / 2U));
                const int width = canvas_string_width(canvas, size);
                canvas_set_color(canvas, ColorWhite);
                canvas_draw_box(canvas, 117 - width, 11, width + 6U, 8);
                canvas_set_color(canvas, ColorBlack);
                canvas_draw_str(canvas, 120 - width, 18, size);
                canvas_set_font(canvas, FontKeyboard);
                for(size_t row = 0U; row < 3U; row++) {
                    const size_t offset = (app->saved_scroll + row) * UHF_TAG_DATA_HEX_PER_LINE;
                    if(offset >= length) break;
                    char line[21];
                    const size_t count = MIN(length - offset, UHF_TAG_DATA_HEX_PER_LINE);
                    uhf_format_hex_bytes_spaced(value + offset, count, line, sizeof(line));
                    canvas_draw_str(canvas, 6, 28 + (int)row * 9, line);
                }
                const size_t lines =
                    (length + UHF_TAG_DATA_HEX_PER_LINE - 1U) / UHF_TAG_DATA_HEX_PER_LINE;
                if(lines > 3U)
                    elements_scrollbar_pos(canvas, 123, 21, 27, app->saved_scroll, lines - 2U);
            }
        }
        canvas_set_font(canvas, FontSecondary);
        static const char* const bank_buttons[] = {"EPC", "TID", "User", "Info"};
        elements_button_left(canvas, bank_buttons[(app->saved_bank + 1U) % 4U]);
        if(app->saved_bank < 3U) elements_button_center(canvas, "Edit");
        if(uhf_saved_write_value(app)[0]) elements_button_right(canvas, "Write");
    }
}

